(function(){
  if (typeof LESSONS === "undefined") return;
  if (typeof STAGES !== "undefined") STAGES[24] = "Bản sạch — Tin 12 (Tin học ứng dụng)";
  if (typeof QUESTION_BANK !== "undefined") QUESTION_BANK.push.apply(QUESTION_BANK, [{"id":"UC-mc-101","type":"mc","topic":"B","grade":12,"level":"easy","question":"Cách kết nối nào phù hợp nhất khi cần chép cả thư mục ảnh dung lượng lớn từ điện thoại sang máy tính?","options":["Bluetooth","Cáp","Gửi qua tin nhắn từng ảnh","Không kết nối được"],"answer":1,"explain":"Cáp cho tốc độ ổn định và không phụ thuộc mạng nên hợp với việc chép khối lượng lớn. Bluetooth chậm và tầm ngắn, chỉ hợp vài tệp nhỏ; gửi từng ảnh qua tin nhắn rất mất công; và tất nhiên vẫn kết nối được."},{"id":"UC-mc-102","type":"mc","topic":"B","grade":12,"level":"easy","question":"Để hai máy tính thấy nhau và chia sẻ thư mục qua mạng không dây, điều kiện cần là gì?","options":["Hai máy phải cùng nối vào một mạng và bật cho phép thấy nhau","Hai máy phải cùng một hãng sản xuất","Hai máy phải cắm chung một sợi cáp","Hai máy phải cùng bật Bluetooth"],"answer":0,"explain":"Chia sẻ thư mục qua Wi-Fi cần hai máy cùng một mạng và bật tính năng cho phép các máy nhìn thấy nhau. Không cần cùng hãng, không cần cáp (vì đang dùng không dây) và Bluetooth là kết nối khác, không phải điều kiện để chia sẻ thư mục mạng."},{"id":"UC-mc-103","type":"mc","topic":"B","grade":12,"level":"medium","question":"Máy in chỉ cắm vào máy của Minh nhưng cả nhóm vẫn in được. Vì sao lệnh in của Huy vẫn ra giấy?","options":["Vì máy in tự động kết nối riêng với mọi máy trong phòng","Vì Huy đã chép sẵn máy in vào USB của mình","Vì máy in được chia sẻ, lệnh in đi qua mạng tới máy của Minh rồi mới ra giấy","Vì máy in in được cả khi máy của Minh đã tắt"],"answer":2,"explain":"Khi chia sẻ máy in, các máy khác thêm máy in đó vào danh sách và gửi lệnh in qua mạng tới máy chủ (máy của Minh) để ra giấy. Máy in không tự nối riêng với mọi máy, không thể chép vào USB, và máy chủ phải đang bật thì lệnh in mới xử lí được."},{"id":"UC-mc-104","type":"mc","topic":"B","grade":12,"level":"medium","question":"Nhóm chia sẻ thư mục chứa ảnh gốc quý mà không muốn ai lỡ tay xoá, nhưng vẫn cho mọi người xem. Nên đặt quyền truy cập nào?","options":["Cho phép cả sửa và xoá để tiện","Không chia sẻ gì cả nên không ai xem được","Cho phép xoá nhưng không cho xem","Chỉ cho phép xem (đọc)"],"answer":3,"explain":"Quyền chỉ xem (đọc) cho phép mọi người mở ảnh nhưng không sửa, không xoá được, đúng nhu cầu bảo vệ ảnh gốc. Mở quyền sửa/xoá dễ mất ảnh; không chia sẻ thì không ai xem được; còn cho xoá mà không cho xem là vô lí và nguy hiểm."},{"id":"UC-mc-105","type":"mc","topic":"B","grade":12,"level":"hard","question":"Đang ngồi làm bài ở quán cà phê dùng Wi-Fi chung, bạn muốn cả nhóm cùng sửa một thư mục nhưng vẫn an toàn. Cách xử lí hợp lí nhất là gì?","options":["Bật chia sẻ thư mục với quyền sửa và để nguyên như vậy cả buổi cho tiện","Chỉ bật chia sẻ trong lúc cùng làm, đặt đúng quyền, rồi tắt chia sẻ khi xong","Tắt hẳn mạng để không ai truy cập được, kể cả nhóm mình","Chia sẻ cho toàn bộ mọi người trong quán để ai giúp cũng được"],"answer":1,"explain":"Nguyên tắc an toàn là chỉ chia sẻ khi cần và tắt khi xong, vì mạng công cộng có người lạ cùng mạng. Để chia sẻ mở suốt buổi khiến người lạ dò tới; tắt hẳn mạng thì nhóm cũng không làm được; chia sẻ cho cả quán là mời người lạ vào dữ liệu của mình."},{"id":"UC-tf-101","type":"tf","topic":"B","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Bluetooth phù hợp để gửi vài tệp nhỏ hoặc nối thiết bị ngoại vi ở khoảng cách gần.","correct":true},{"text":"Cáp thường cho tốc độ ổn định và không phụ thuộc vào mạng khi truyền dữ liệu.","correct":true},{"text":"Muốn hai máy chia sẻ thư mục qua Wi-Fi thì hai máy phải cùng bật Bluetooth.","correct":false},{"text":"Kết nối bằng cáp luôn thất bại nếu điện thoại đang ở chế độ chỉ sạc.","correct":true}],"explain":"(1) Đúng — đó là thế mạnh của Bluetooth. (2) Đúng — cáp ổn định và không cần cấu hình mạng. (3) Sai — chia sẻ thư mục qua Wi-Fi cần cùng mạng chứ không cần Bluetooth. (4) Đúng — ở chế độ chỉ sạc, máy tính không thấy dữ liệu, phải chuyển sang chế độ truyền tệp."},{"id":"UC-tf-102","type":"tf","topic":"B","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Chia sẻ máy in giúp nhiều máy trong cùng mạng cùng in qua một máy in chung.","correct":true},{"text":"Khi máy chủ gắn máy in đã tắt, các máy khác vẫn in được bình thường.","correct":false},{"text":"Chia sẻ màn hình giúp nhiều người cùng nhìn thấy nội dung đang hiện trên một màn hình.","correct":true},{"text":"Chia sẻ thư mục cho phép máy khác mở dữ liệu qua mạng mà không cần chép ra USB.","correct":true}],"explain":"(1) Đúng — đó là mục đích của chia sẻ máy in. (2) Sai — lệnh in đi qua máy chủ nên máy chủ phải đang bật. (3) Đúng — chia sẻ màn hình để nhiều người cùng xem, ví dụ khi thuyết trình. (4) Đúng — thư mục chia sẻ được truy cập trực tiếp qua mạng."},{"id":"UC-tf-103","type":"tf","topic":"B","grade":12,"level":"hard","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Đặt quyền chỉ xem cho một thư mục chia sẻ giúp người khác không sửa hay xoá được dữ liệu trong đó.","correct":true},{"text":"Nên để mọi thư mục ở chế độ chia sẻ thường xuyên trên Wi-Fi công cộng cho tiện dùng.","correct":false},{"text":"Bước ghép đôi Bluetooth thường hiện một mã để hai bên xác nhận đúng thiết bị muốn nối.","correct":true},{"text":"Nếu có yêu cầu ghép đôi Bluetooth lạ tự hiện lên, cứ chấp nhận vì mọi kết nối đều an toàn.","correct":false}],"explain":"(1) Đúng — quyền chỉ xem bảo vệ dữ liệu khỏi bị sửa/xoá. (2) Sai — trên mạng công cộng người lạ có thể dò tới, chỉ nên chia sẻ khi cần và tắt khi xong. (3) Đúng — mã ghép đôi để xác nhận đúng thiết bị. (4) Sai — yêu cầu ghép đôi lạ nên từ chối vì có thể là thiết bị lạ đang thử kết nối."},{"id":"UC-mc-201","type":"mc","topic":"E","grade":12,"level":"easy","question":"Trong bước chuẩn bị dự án web, ba câu hỏi nào nên được trả lời đầu tiên?","options":["Dùng màu nền gì, phông chữ gì, cỡ chữ bao nhiêu","Trang để làm gì, ai sẽ xem, cần truyền đạt nội dung gì","Đặt tên tệp ảnh ra sao, nén ảnh nặng bao nhiêu","Trang có bao nhiêu dòng mã, dùng thẻ HTML nào"],"answer":1,"explain":"Bước lập kế hoạch bắt đầu từ mục đích, đối tượng người xem và nội dung chính — đây là nền móng định hướng mọi quyết định sau. Màu sắc, phông chữ, đặt tên ảnh hay số dòng mã đều là chi tiết kĩ thuật đến sau khi đã rõ ba câu hỏi trên."},{"id":"UC-mc-202","type":"mc","topic":"E","grade":12,"level":"easy","question":"Wireframe (bản phác thảo bố cục) chủ yếu dùng để làm gì?","options":["Chọn màu sắc và hình ảnh thật cho trang","Viết sẵn toàn bộ nội dung văn bản của trang","Vẽ nháp khung, đánh dấu vị trí đặt các khối trên trang","Kiểm tra tốc độ tải trang trên điện thoại"],"answer":2,"explain":"Wireframe là bản vẽ nháp bằng các ô chữ nhật để thống nhất vị trí các khối (đầu trang, thân, chân trang), chưa quan tâm màu mè hay ảnh thật. Việc chọn màu/ảnh, viết nội dung và kiểm tra tốc độ là các bước khác, không phải mục đích của wireframe."},{"id":"UC-mc-203","type":"mc","topic":"E","grade":12,"level":"medium","question":"Vì sao nên tách riêng một thư mục chứa ảnh trong dự án web thay vì để mọi tệp lẫn lộn một chỗ?","options":["Để ảnh tự động đẹp hơn và sắc nét hơn","Để đường dẫn tới ảnh rõ ràng, dễ quản lí và tránh lạc tệp","Để trang web chạy được mà không cần trình duyệt","Để không phải đặt tên cho các tệp ảnh nữa"],"answer":1,"explain":"Tổ chức thư mục gọn (tách thư mục ảnh) giúp đường dẫn khi trang gọi ảnh luôn rõ ràng, dễ quản lí và tránh hỏng liên kết khi số tệp tăng. Nó không làm ảnh đẹp hơn, không thay thế trình duyệt, và vẫn cần đặt tên ảnh có nghĩa."},{"id":"UC-mc-204","type":"mc","topic":"E","grade":12,"level":"medium","question":"Sơ đồ trang (sitemap) của một dự án web thể hiện điều gì?","options":["Mã nguồn chi tiết của từng trang","Danh sách màu và phông chữ dùng chung","Các trang cần làm và đường liên kết bấm giữa chúng","Dung lượng của từng tấm ảnh trên trang"],"answer":2,"explain":"Sơ đồ trang biểu diễn mỗi trang là một ô và mũi tên chỉ đường bấm giữa các trang, giúp thấy trước số trang cần làm và cách chúng nối nhau. Nó không chứa mã nguồn, không phải bảng màu/phông, cũng không phải thông tin dung lượng ảnh."},{"id":"UC-mc-205","type":"mc","topic":"E","grade":12,"level":"hard","question":"Nhóm bạn định làm trang web bán bánh handmade cho các bạn trong trường, gồm bốn trang: trang chủ, thực đơn, cách đặt hàng, liên hệ. Việc nào sau đây thuộc bước CHUẨN BỊ dự án (chưa dựng trang)?","options":["Vẽ sơ đồ bốn trang và đánh mũi tên chỉ cách bấm qua lại giữa chúng","Gõ mã tạo thanh điều hướng và kiểm tra bấm thử từng mục","Chỉnh cho chữ trên trang chủ đổi màu khi rê chuột vào","Xuất trang và tải lên máy chủ để bạn bè truy cập"],"answer":0,"explain":"Vẽ sơ đồ trang và các liên kết là hoạt động lập kế hoạch, làm trên giấy trước khi dựng trang — đúng bước chuẩn bị. Gõ mã thanh điều hướng, chỉnh hiệu ứng đổi màu, hay xuất và tải trang lên máy chủ đều là các bước thực hiện và hoàn thiện diễn ra sau bước chuẩn bị."},{"id":"UC-tf-201","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau về việc xác định mục đích và nội dung trang web đúng hay sai:","statements":[{"text":"Hiểu rõ đối tượng người xem giúp quyết định giọng văn, cỡ chữ và màu sắc phù hợp.","correct":true},{"text":"Nên đưa càng nhiều nội dung càng tốt, kể cả những phần không phục vụ mục đích.","correct":false},{"text":"Xác định mục đích trang giúp lọc ra danh sách nội dung chính cần có.","correct":true},{"text":"Mục đích của trang chỉ cần nghĩ tới sau khi đã dựng xong toàn bộ trang.","correct":false}],"explain":"(1) Đúng — biết ai xem thì mới chọn được giọng văn và cách trình bày phù hợp. (2) Sai — nội dung không phục vụ mục đích cần mạnh dạn bỏ để trang khỏi loãng. (3) Đúng — từ mục đích ta suy ra nội dung chính cần có. (4) Sai — mục đích phải được xác định ngay từ đầu, trước khi dựng trang."},{"id":"UC-tf-202","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau về bố cục và wireframe đúng hay sai:","statements":[{"text":"Đầu trang thường chứa tên hoặc logo và thanh điều hướng.","correct":true},{"text":"Thân trang là khu vực chứa nội dung chính của trang.","correct":true},{"text":"Wireframe bắt buộc phải dùng đúng màu sắc và ảnh thật ngay từ đầu.","correct":false},{"text":"Chân trang thường đặt ở phần trên cùng của trang, phía trên đầu trang.","correct":false}],"explain":"(1) Đúng — logo và thanh điều hướng thường nằm ở đầu trang cho dễ thấy. (2) Đúng — thân trang là phần giữa, lớn nhất, chứa nội dung chính. (3) Sai — wireframe chỉ vẽ nháp khung bằng ô chữ nhật, chưa cần màu và ảnh thật. (4) Sai — chân trang nằm ở phần dưới cùng, không phải trên cùng."},{"id":"UC-tf-203","type":"tf","topic":"E","grade":12,"level":"hard","question":"Cho biết mỗi phát biểu sau về chuẩn bị tư liệu và sơ đồ trang đúng hay sai:","statements":[{"text":"Đổi tên ảnh thành tên có nghĩa và nén ảnh cho nhẹ là việc nên làm khi chuẩn bị tư liệu.","correct":true},{"text":"Một sơ đồ trang tốt nên để từ bất kì trang nào người xem cũng quay về được trang chủ.","correct":true},{"text":"Nên để một số trang không có đường bấm nào dẫn tới để trang web bí ẩn hơn.","correct":false},{"text":"Vẽ wireframe và sơ đồ trên giấy chỉ làm mất thời gian, không giúp ích gì cho việc dựng trang.","correct":false}],"explain":"(1) Đúng — tên ảnh có nghĩa và ảnh nhẹ giúp quản lí tốt và trang tải nhanh. (2) Đúng — cho phép quay về trang chủ từ mọi trang là nguyên tắc điều hướng thân thiện. (3) Sai — trang không có đường bấm dẫn tới sẽ bị 'lạc', người xem không tới được; đây là lỗi cần tránh. (4) Sai — vẽ nháp trước tiết kiệm nhiều giờ chỉnh sửa và giúp dựng trang nhanh, đúng hơn."},{"id":"UC-mc-301","type":"mc","topic":"E","grade":12,"level":"easy","question":"Thẻ nào được dùng để gom logo và tiêu đề chính thành một khối phần đầu trang có ý nghĩa?","options":["header","footer","table","form"],"answer":0,"explain":"Thẻ header đóng vai trò chiếc hộp có ý nghĩa gom logo và tiêu đề chính thành khối đầu trang. footer là phần chân trang, đặt ở cuối. table dùng để trình bày bảng dữ liệu. form dùng để tạo biểu mẫu nhập liệu, đều không phải khu vực đầu trang."},{"id":"UC-mc-302","type":"mc","topic":"E","grade":12,"level":"easy","question":"Khi chèn ảnh logo, vì sao nên ghi thêm phần mô tả ảnh (thuộc tính alt)?","options":["Để ảnh tự động phóng to khi rê chuột vào","Để logo luôn nằm chính giữa dải đầu trang","Để giúp người khiếm thị nghe được và hiện ra khi ảnh không tải được","Để giảm dung lượng tệp ảnh logo"],"answer":2,"explain":"Phần mô tả alt giúp phần mềm đọc màn hình đọc cho người khiếm thị và hiện ra thay ảnh khi hình không tải được. Nó không phóng to ảnh khi rê chuột, không quyết định vị trí canh giữa (việc đó do CSS), và cũng không làm thay đổi dung lượng tệp ảnh."},{"id":"UC-mc-303","type":"mc","topic":"E","grade":12,"level":"medium","question":"Ảnh logo gốc rất to so với chỗ cần đặt. Cách chỉnh kích thước nào giúp logo vừa dải đầu trang mà không bị méo?","options":["Ép cả chiều cao và chiều rộng bằng hai số bất kì cho vừa mắt","Đặt một chiều cao cố định và để chiều rộng tự co theo","Giữ nguyên kích thước gốc và để trình duyệt tự cắt bớt","Xoá bớt màu trong ảnh để ảnh nhỏ lại"],"answer":1,"explain":"Cố định chiều cao (ví dụ 48px) rồi để chiều rộng tự co theo giúp ảnh thu nhỏ mà vẫn giữ đúng tỉ lệ, không bị méo. Ép cả hai chiều bằng số không cân xứng làm ảnh bị kéo dẹt hoặc bè ra. Giữ nguyên kích thước gốc thì logo vẫn quá to. Xoá màu không làm ảnh nhỏ lại về kích thước hiển thị."},{"id":"UC-mc-304","type":"mc","topic":"E","grade":12,"level":"medium","question":"Lan muốn dải đầu trang có nền xanh, chữ trắng và logo cùng tiêu đề được canh giữa. Bạn nên dùng công cụ nào để làm những việc này?","options":["Viết thêm nhiều thẻ header lồng nhau","Đổi tên tệp trang thành index để tự có màu","Tăng độ phân giải màn hình máy tính","Dùng CSS để đặt màu nền, màu chữ và bố cục canh giữa cho header"],"answer":3,"explain":"Màu nền, màu chữ và cách canh giữa đều là việc của CSS áp lên khối header. Lồng nhiều thẻ header không tạo ra màu và còn sai ý nghĩa. Đổi tên tệp không sinh ra màu sắc hay bố cục. Độ phân giải màn hình không liên quan tới việc trang trí phần đầu trang."},{"id":"UC-mc-305","type":"mc","topic":"E","grade":12,"level":"hard","question":"Website Câu lạc bộ Sách có ba trang. Sau khi sao chép phần đầu sang trang giới thiệu, logo ở trang đó chỉ hiện một khung vỡ kèm dòng chữ mô tả, còn nền và tiêu đề vẫn đúng. Nguyên nhân hợp lí nhất là gì?","options":["Đường dẫn tới tệp logo trên trang giới thiệu bị sai nên ảnh không tải được","Thẻ header không dùng được ở trang thứ hai của website","Màu nền xanh đã che mất ảnh logo","Thuộc tính alt làm ảnh biến mất"],"answer":0,"explain":"Nền và tiêu đề vẫn đúng chứng tỏ CSS và cấu trúc header ổn, chỉ riêng ảnh không hiện và bày ra khung vỡ kèm chữ mô tả alt, đúng dấu hiệu của đường dẫn logo sai nên ảnh không tải được. header dùng được ở mọi trang. Màu nền không che ảnh đặt trên nó. Thuộc tính alt chỉ hiện ra khi ảnh lỗi, không phải nguyên nhân làm ảnh mất."},{"id":"UC-tf-301","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Phần đầu trang thường gồm logo và tiêu đề chính, đóng vai trò nhận diện website.","correct":true},{"text":"Thẻ header tự nó vẽ ra màu nền và khung viền cho phần đầu trang.","correct":false},{"text":"Nên giữ phần đầu ngắn gọn, tránh nhồi quá nhiều chữ và ảnh.","correct":true},{"text":"Phần đầu trang bắt buộc phải đặt ở cuối tệp, sau nội dung chính.","correct":false}],"explain":"(1) Đúng — logo và tiêu đề chính là bộ mặt nhận diện của website. (2) Sai — header chỉ là chiếc hộp có ý nghĩa, màu nền và viền phải do CSS tạo ra. (3) Đúng — phần đầu gọn gàng giúp người xem không rối mắt và không đẩy nội dung xuống quá thấp. (4) Sai — phần đầu nằm trên cùng, xuất hiện đầu tiên chứ không đặt ở cuối tệp."},{"id":"UC-tf-302","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Logo là một tấm ảnh nên được chèn vào trang bằng thẻ ảnh.","correct":true},{"text":"Cố định chiều cao ảnh rồi để chiều rộng tự co giúp logo không bị méo.","correct":true},{"text":"Ép cả chiều cao lẫn chiều rộng bằng hai số không cân xứng vẫn giữ ảnh đẹp như gốc.","correct":false},{"text":"Tiêu đề chính hiển thị trên dải đầu trang chính là dòng chữ nằm trên tab trình duyệt.","correct":false}],"explain":"(1) Đúng — logo là ảnh nên dùng thẻ ảnh và trỏ tới tệp hình. (2) Đúng — cố định một chiều và để chiều kia tự co giữ đúng tỉ lệ, ảnh không méo. (3) Sai — ép hai chiều lệch tỉ lệ làm ảnh bị kéo dẹt hoặc bè ra. (4) Sai — tiêu đề chính trên trang khác với dòng tiêu đề nhỏ trên tab trình duyệt; đó là hai nội dung riêng."},{"id":"UC-tf-303","type":"tf","topic":"E","grade":12,"level":"hard","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Gom quy tắc trang trí header vào một tệp CSS chung giúp sửa một chỗ là đổi cả website.","correct":true},{"text":"Mỗi trang tự đặt màu nền header một kiểu sẽ giúp website trông nhất quán hơn.","correct":false},{"text":"Bố cục linh hoạt cho header giúp đặt logo bên trái và tiêu đề canh giữa gọn gàng.","correct":true},{"text":"Muốn phần đầu giống nhau ở mọi trang thì mỗi trang phải dùng một cấu trúc header khác nhau.","correct":false}],"explain":"(1) Đúng — để quy tắc ở một tệp CSS chung thì sửa một nơi là mọi trang cùng đổi. (2) Sai — mỗi trang một màu khiến website chắp vá chứ không nhất quán. (3) Đúng — bố cục linh hoạt cho phép canh logo và tiêu đề theo trục rất gọn. (4) Sai — muốn nhất quán thì mọi trang phải dùng cùng một cấu trúc header, không phải mỗi trang một kiểu."},{"id":"UC-mc-401","type":"mc","topic":"E","grade":12,"level":"easy","question":"Trong một trang web, thẻ nào dùng để gói toàn bộ nội dung chính mà người xem thật sự tìm đến?","options":["`header`","`main`","`footer`","`title`"],"answer":1,"explain":"Nội dung chính của trang được đặt trong thẻ `main`, đó là phần thân trang. `header` là phần đầu trang chứa logo và tiêu đề. `footer` là chân trang chứa thông tin phụ như liên hệ và bản quyền. `title` chỉ đặt tên hiện trên thanh tiêu đề của trình duyệt, không chứa nội dung nhìn thấy trong trang."},{"id":"UC-mc-402","type":"mc","topic":"E","grade":12,"level":"easy","question":"Thông tin nào sau đây phù hợp để đặt ở chân trang (`footer`) của một trang web?","options":["Đoạn văn giới thiệu chi tiết về câu lạc bộ","Bộ ảnh minh hoạ các buổi hoạt động","Dòng bản quyền và thông tin liên hệ","Tiêu đề lớn và logo của trang"],"answer":2,"explain":"Chân trang là nơi chứa thông tin phụ nhưng cần có như dòng bản quyền và thông tin liên hệ. Đoạn giới thiệu và bộ ảnh hoạt động là nội dung chính, thuộc phần thân trang `main`. Tiêu đề lớn và logo là dấu hiệu nhận diện, thuộc phần đầu trang `header` chứ không phải chân trang."},{"id":"UC-mc-403","type":"mc","topic":"E","grade":12,"level":"medium","question":"Nhóm của Lan muốn chia phần thân trang thành các mục có chủ đề riêng như 'Về câu lạc bộ', 'Hình ảnh hoạt động', 'Sự kiện sắp tới'. Cách làm gọn gàng nhất là gì?","options":["Gõ tất cả nội dung liền nhau, không bọc thẻ nào","Bọc mỗi mục trong một thẻ `section` riêng, mỗi mục mở đầu bằng tiêu đề","Đặt cả ba mục vào trong thẻ `footer`","Dùng một thẻ `img` để bao lấy cả ba mục"],"answer":1,"explain":"Chia thân trang thành các khu bằng cách bọc mỗi mục trong một `section` và mở đầu bằng tiêu đề `h2` giúp trang mạch lạc, dễ đọc và dễ sửa từng khu. Gõ liền nhau khiến trang rối. `footer` là chân trang cho thông tin phụ, không dùng để chứa các mục nội dung chính. Thẻ `img` chỉ để chèn một hình ảnh, không dùng để bao các mục nội dung."},{"id":"UC-mc-404","type":"mc","topic":"E","grade":12,"level":"medium","question":"Sau khi chia thân trang thành các khu, các khu vẫn dính sát vào nhau trông rất chật. Thuộc tính CSS nào giúp giãn các khu ra xa nhau?","options":["`margin`","`color`","`src`","`alt`"],"answer":0,"explain":"`margin` tạo khoảng cách bên ngoài giữa các khu, giúp chúng giãn ra xa nhau. `color` chỉ đổi màu chữ, không liên quan tới khoảng cách. `src` và `alt` không phải thuộc tính CSS mà là thuộc tính của thẻ `img` (đường dẫn ảnh và văn bản thay thế), nên không dùng để tạo khoảng cách giữa các khu."},{"id":"UC-mc-405","type":"mc","topic":"E","grade":12,"level":"hard","question":"Một bạn viết CSS `footer { background-color: #222; color: white; text-align: center; }` cho dự án. Kết quả nhìn thấy trên trang là gì?","options":["Toàn bộ trang đổi thành nền tối, kể cả phần thân","Chỉ riêng chân trang có nền tối, chữ trắng và nội dung canh giữa","Chân trang bị ẩn đi, không còn hiển thị","Các thẻ `section` trong thân trang được canh giữa"],"answer":1,"explain":"Quy tắc CSS này nhắm riêng vào thẻ `footer` nên chỉ chân trang bị ảnh hưởng: nền tối màu #222, chữ màu trắng và nội dung canh giữa. Nó không tác động lên toàn trang hay phần thân vì chỉ chọn `footer`. CSS này chỉ tạo kiểu chứ không ẩn chân trang. Các `section` trong thân trang không nằm trong `footer` nên không bị canh giữa theo quy tắc này."},{"id":"UC-tf-401","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Phần thân trang chứa nội dung chính như đoạn văn, hình ảnh và danh sách.","correct":true},{"text":"Một trang web thường gồm ba mảng theo chiều dọc: đầu trang, thân trang và chân trang.","correct":true},{"text":"Nội dung chính của trang nên đặt trong thẻ `footer`.","correct":false},{"text":"Chia thân trang thành các khu giúp trang mạch lạc và dễ sửa riêng từng khu.","correct":true}],"explain":"(1) Đúng — thân trang là nơi đặt nội dung chính gồm đoạn văn, hình ảnh, danh sách. (2) Đúng — trang thường có ba mảng đầu, thân, chân xếp từ trên xuống. (3) Sai — nội dung chính đặt trong `main`, còn `footer` chỉ dành cho thông tin phụ như liên hệ và bản quyền. (4) Đúng — chia khu giúp trang gọn, muốn sửa khu nào chỉ tìm đúng khu đó."},{"id":"UC-tf-402","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Thẻ `footer` dùng để khép lại trang và chứa thông tin liên hệ, bản quyền.","correct":true},{"text":"Kí hiệu `&copy;` được dùng để hiện ra dấu bản quyền © trên trang.","correct":true},{"text":"Chân trang chỉ hiển thị khi phần thân trang có nội dung thật dài.","correct":false},{"text":"Thông tin liên hệ như email và số điện thoại thường được đặt ở chân trang.","correct":true}],"explain":"(1) Đúng — `footer` là chân trang, nơi để liên hệ và bản quyền. (2) Đúng — `&copy;` là mã để hiện dấu bản quyền ©. (3) Sai — chân trang luôn hiển thị dù thân trang dài hay ngắn, vì nó nằm trong thẻ `footer` chứ không phụ thuộc độ dài nội dung. (4) Đúng — email, số điện thoại là thông tin liên hệ hay được gom xuống chân trang."},{"id":"UC-tf-403","type":"tf","topic":"E","grade":12,"level":"hard","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Thuộc tính `padding` tạo khoảng đệm bên trong một khu để chữ không dán sát mép.","correct":true},{"text":"Quên đóng thẻ, ví dụ mở `<section>` mà thiếu `</section>`, có thể làm bố cục trang bị vỡ.","correct":true},{"text":"`text-align: center` dùng để đổi màu nền của một khu.","correct":false},{"text":"Bọc nội dung chính trong `main` không giúp ích gì cho việc áp CSS theo khu.","correct":false}],"explain":"(1) Đúng — `padding` tạo khoảng đệm bên trong, giữ cho chữ cách mép của khu. (2) Đúng — thiếu thẻ đóng khiến các khu lồng nhầm vào nhau và bố cục vỡ. (3) Sai — `text-align: center` canh giữa nội dung theo chiều ngang, còn đổi màu nền là việc của `background-color`. (4) Sai — bọc nội dung trong `main` và chia khu bằng `section` giúp cấu trúc rõ ràng, nhờ đó áp CSS theo từng loại thẻ dễ dàng hơn."},{"id":"UC-mc-501","type":"mc","topic":"E","grade":12,"level":"easy","question":"Thẻ HTML nào dùng để tạo một liên kết từ trang này sang trang khác?","options":["Thẻ `a`","Thẻ `img`","Thẻ `nav`","Thẻ `head`"],"answer":0,"explain":"Thẻ `a` (anchor) tạo liên kết, với địa chỉ đích ghi trong thuộc tính `href`. Thẻ `img` chèn ảnh, thẻ `nav` chỉ để bọc khu điều hướng chứ tự nó không tạo liên kết, còn `head` là phần khai báo thông tin của trang."},{"id":"UC-mc-502","type":"mc","topic":"E","grade":12,"level":"easy","question":"Trong đoạn `<a href=\"lienhe.html\">Liên hệ</a>`, phần nào là địa chỉ trang mà trình duyệt sẽ mở khi người xem nhấn vào?","options":["Chữ Liên hệ","Giá trị `lienhe.html` trong href","Tên thẻ a","Dấu ngoặc nhọn"],"answer":1,"explain":"Địa chỉ đích nằm trong thuộc tính `href`, ở đây là `lienhe.html`. Chữ Liên hệ chỉ là phần hiển thị để người xem bấm; tên thẻ và dấu ngoặc là cú pháp HTML, không phải địa chỉ trang."},{"id":"UC-mc-503","type":"mc","topic":"E","grade":12,"level":"medium","question":"Vì sao khi các trang nằm cùng một thư mục, ta nên dùng liên kết tương đối (chỉ ghi tên tệp) thay vì địa chỉ đầy đủ?","options":["Vì liên kết tương đối làm trang tải nhanh hơn nhiều lần","Vì trình duyệt chỉ hiểu được tên tệp ngắn","Vì khi chép hay tải cả thư mục lên mạng, các liên kết vẫn chạy đúng do các tệp vẫn nằm cạnh nhau","Vì liên kết tương đối tự động tạo thanh điều hướng"],"answer":2,"explain":"Liên kết tương đối trỏ tới tệp nằm ngay cạnh trang hiện tại, nên di chuyển cả thư mục đi đâu thì liên kết vẫn đúng. Nó không quyết định tốc độ tải, trình duyệt vẫn hiểu địa chỉ đầy đủ, và nó cũng không tự tạo menu."},{"id":"UC-mc-504","type":"mc","topic":"E","grade":12,"level":"medium","question":"Cách làm nào sau đây phù hợp nhất khi dựng thanh điều hướng cho website nhiều trang?","options":["Mỗi trang một menu khác nhau, đặt ở vị trí khác nhau cho đỡ nhàm","Đặt menu giống hệt nhau và cùng vị trí trên mọi trang, đủ liên kết tới các trang chính","Chỉ trang chủ mới có menu, các trang khác thì không cần","Gom tất cả liên kết vào phần chân trang và bỏ trống phần đầu"],"answer":1,"explain":"Menu nên nhất quán về nội dung và vị trí trên mọi trang để người xem không bị lạc và luôn chuyển trang được. Menu khác nhau mỗi trang, chỉ trang chủ có menu, hay bỏ trống phần đầu đều làm việc điều hướng rối và thiếu."},{"id":"UC-mc-505","type":"mc","topic":"E","grade":12,"level":"hard","question":"Em có tệp trang chủ tên `index.html` và một ảnh `logo.png` đặt trong thư mục con tên `anh`. Trong `index.html`, đường dẫn tương đối đúng để chèn ảnh này là gì?","options":["`logo.png`","`anh/logo.png`","`index.html/logo.png`","`png/anh/logo`"],"answer":1,"explain":"Ảnh nằm trong thư mục con `anh`, nên từ trang chủ phải ghi `anh/logo.png`, nghĩa là vào thư mục anh rồi lấy tệp logo.png. Ghi `logo.png` là tìm ngay cạnh index.html nên không thấy; `index.html/logo.png` coi tệp trang như thư mục là sai; `png/anh/logo` sai cả thứ tự lẫn tên."},{"id":"UC-tf-501","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Phần chữ nằm giữa cặp thẻ `<a>` và `</a>` là phần người xem nhìn thấy và bấm vào.","correct":true},{"text":"Thuộc tính `href` ghi địa chỉ trang mà liên kết sẽ mở.","correct":true},{"text":"Một liên kết bắt buộc chữ hiển thị phải trùng đúng tên tệp đích.","correct":false},{"text":"Thẻ `a` chỉ có thể liên kết tới trang, không thể liên kết tới tệp ảnh.","correct":false}],"explain":"(1) Đúng — đó là phần hiển thị của liên kết. (2) Đúng — href chứa địa chỉ đích. (3) Sai — chữ hiển thị đặt tuỳ ý, chỉ href mới phải trỏ đúng tên tệp. (4) Sai — href có thể trỏ tới nhiều loại tệp, không riêng gì trang."},{"id":"UC-tf-502","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Thanh điều hướng về bản chất là nhiều thẻ `a` gom lại, thường bọc trong thẻ `nav`.","correct":true},{"text":"Đánh dấu mục đang mở giúp người xem biết mình đang ở trang nào.","correct":true},{"text":"Menu nên đặt ở vị trí khác nhau trên mỗi trang để trang thêm sinh động.","correct":false},{"text":"Menu của trang chủ không cần chứa liên kết trỏ về chính trang chủ.","correct":true}],"explain":"(1) Đúng — menu là nhóm liên kết, hay bọc trong nav. (2) Đúng — làm nổi mục đang mở giúp định hướng. (3) Sai — menu nên nhất quán về vị trí trên mọi trang để người xem không lạc. (4) Đúng — đang ở trang chủ thì bấm về trang chủ chẳng đi đâu, nên mục đó có thể để tĩnh; tuy vậy để đồng bộ, nhiều trang vẫn giữ mục Trang chủ trong menu."},{"id":"UC-tf-503","type":"tf","topic":"E","grade":12,"level":"hard","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Trên nhiều máy chủ, `TrangChu.html` và `trangchu.html` bị coi là hai tệp khác nhau.","correct":true},{"text":"Liên kết tương đối chỉ chạy được khi mở tệp trên máy, tải lên mạng sẽ hỏng.","correct":false},{"text":"Đường dẫn `anh/logo.png` nghĩa là tệp logo.png nằm trong thư mục con tên anh.","correct":true},{"text":"Đặt tên tệp có dấu cách và tiếng Việt có dấu là cách làm được khuyến nghị.","correct":false}],"explain":"(1) Đúng — nhiều máy chủ phân biệt hoa thường nên href phải gõ y hệt tên tệp thật. (2) Sai — liên kết tương đối vẫn chạy khi tải lên mạng miễn các tệp giữ đúng vị trí tương đối. (3) Đúng — dấu gạch chéo cho biết logo.png nằm trong thư mục con anh. (4) Sai — nên dùng chữ không dấu, không dấu cách để tránh lỗi liên kết."},{"id":"UC-mc-601","type":"mc","topic":"E","grade":12,"level":"easy","question":"Để tạo một biểu mẫu thu thập thông tin trên trang web, ta bọc các ô nhập và nút gửi trong thẻ nào?","options":["`main`","`form`","`footer`","`img`"],"answer":1,"explain":"Toàn bộ một biểu mẫu được gói trong thẻ `form`, nhờ đó khi bấm gửi thì mọi ô nhập bên trong đi cùng nhau một lượt. `main` là thân trang chứa nội dung chính để đọc, `footer` là chân trang chứa thông tin phụ, còn `img` chỉ để chèn một hình ảnh, không dùng để bọc biểu mẫu."},{"id":"UC-mc-602","type":"mc","topic":"E","grade":12,"level":"easy","question":"Nhóm Lan muốn một ô cho người dùng nhập địa chỉ email và được trình duyệt tự nhắc khi gõ sai dạng. Nên dùng loại trường nào?","options":["Ô văn bản thường (`text`)","Ô chọn một trong nhiều (`radio`)","Vùng văn bản nhiều dòng (`textarea`)","Ô email (`email`)"],"answer":3,"explain":"Ô nhập loại `email` được trình duyệt hiểu là để điền địa chỉ email nên có thể tự nhắc khi giá trị nhập vào không đúng dạng email. Ô `text` chỉ nhận chuỗi bất kì mà không kiểm tra. `radio` dùng để chọn một trong các lựa chọn, còn `textarea` là khung rộng nhiều dòng cho đoạn văn dài, cả hai đều không dành cho việc nhập một địa chỉ email."},{"id":"UC-mc-603","type":"mc","topic":"E","grade":12,"level":"medium","question":"Người dùng đã điền xong các ô trong biểu mẫu và muốn chuyển thông tin đi. Thành phần nào của biểu mẫu đảm nhận việc này?","options":["Nút gửi (nút loại `submit`)","Nhãn `label`","Vùng văn bản `textarea`","Thẻ `footer`"],"answer":0,"explain":"Nút gửi loại `submit` khi được bấm sẽ khiến trình duyệt gom hết dữ liệu trong `form` và gửi đi, nên nó đảm nhận việc chuyển thông tin. `label` chỉ là nhãn ghi rõ ô để điền gì, `textarea` là một ô nhập cho đoạn dài, còn `footer` là chân trang, không liên quan tới việc gửi biểu mẫu."},{"id":"UC-mc-604","type":"mc","topic":"E","grade":12,"level":"medium","question":"Nhãn (`label`) gắn với một ô nhập trong biểu mẫu có tác dụng chính là gì?","options":["Tự động đổi màu nền của ô nhập","Ẩn ô nhập đi để trang gọn hơn","Cho biết ô đó để điền gì, giúp dễ dùng và thân thiện với trợ năng","Thay cho nút gửi để chuyển dữ liệu biểu mẫu đi"],"answer":2,"explain":"Nhãn ghi rõ ô để điền thông tin gì; khi gắn đúng qua `for` khớp `id`, bấm vào chữ nhãn là con trỏ nhảy vào ô và phần mềm đọc màn hình đọc kèm nhãn, giúp cả người khiếm thị dùng được. Nhãn không đổi màu nền (việc của CSS), không ẩn ô nhập, và cũng không gửi dữ liệu đi (việc của nút `submit`)."},{"id":"UC-mc-605","type":"mc","topic":"E","grade":12,"level":"hard","question":"Phiếu đăng ký câu lạc bộ có mục 'Nhóm hoạt động bạn muốn tham gia' và cho phép chọn cùng lúc nhiều nhóm (đọc sách, review sách, hậu cần...). Loại trường phù hợp nhất là gì?","options":["Ô chọn một trong nhiều (`radio`), vì mỗi lần chỉ chọn được đúng một mục","Ô đánh dấu (`checkbox`), vì cho phép tích chọn nhiều mục cùng lúc","Ô email (`email`), vì cần địa chỉ để liên lạc lại","Nút gửi (`submit`), vì đây là bước cuối của biểu mẫu"],"answer":1,"explain":"Khi cần chọn nhiều mục cùng lúc, ô đánh dấu `checkbox` là phù hợp vì mỗi ô tích độc lập, người dùng tích được bao nhiêu nhóm tuỳ thích. `radio` chỉ cho chọn đúng một nên không đáp ứng được yêu cầu chọn nhiều. Ô `email` dùng để nhập địa chỉ email, không liên quan tới việc chọn nhóm. Nút `submit` chỉ để gửi cả phiếu đi, không phải trường để chọn lựa."},{"id":"UC-tf-601","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Thẻ `form` dùng để gói các ô nhập và nút gửi của một biểu mẫu.","correct":true},{"text":"Nút gửi loại `submit` khi bấm sẽ chuyển thông tin người dùng đã điền đi.","correct":true},{"text":"Một biểu mẫu bắt buộc chỉ được có đúng một ô nhập duy nhất.","correct":false},{"text":"Ô email (`email`) giúp trình duyệt nhắc khi địa chỉ nhập vào không đúng dạng.","correct":true}],"explain":"(1) Đúng — mọi ô nhập và nút gửi của biểu mẫu đều nằm trong thẻ `form`. (2) Đúng — nút `submit` gom dữ liệu trong `form` rồi gửi đi. (3) Sai — một biểu mẫu có thể có nhiều ô nhập khác nhau, ví dụ họ tên, email, lời nhắn. (4) Đúng — ô `email` được trình duyệt hiểu là để nhập email nên có thể tự nhắc khi sai dạng."},{"id":"UC-tf-602","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Vùng văn bản (`textarea`) phù hợp để nhập đoạn dài nhiều dòng như lời nhắn.","correct":true},{"text":"Ô đánh dấu (`checkbox`) cho phép người dùng chọn nhiều mục cùng lúc.","correct":true},{"text":"Ô chọn một trong nhiều (`radio`) cho phép chọn tất cả các lựa chọn cùng một lúc.","correct":false},{"text":"Danh sách xổ xuống (`select`) giúp chọn một mục từ nhiều mục mà không chiếm nhiều chỗ.","correct":true}],"explain":"(1) Đúng — `textarea` là khung rộng nhiều dòng, hợp cho đoạn dài. (2) Đúng — `checkbox` tích được nhiều mục độc lập cùng lúc. (3) Sai — `radio` chỉ cho chọn đúng một trong các lựa chọn, chọn mục này thì bỏ mục kia. (4) Đúng — `select` bung ra danh sách để chọn một mục, gọn chỗ trên trang."},{"id":"UC-tf-603","type":"tf","topic":"E","grade":12,"level":"hard","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Nhãn (`label`) được gắn với ô nhập bằng cách cho `for` của nhãn khớp với `id` của ô.","correct":true},{"text":"Khi nhãn gắn đúng, bấm vào chữ nhãn thì con trỏ nhảy vào đúng ô nhập tương ứng.","correct":true},{"text":"Biểu mẫu không có nhãn vẫn dễ dùng như nhau với người khiếm thị dùng phần mềm đọc màn hình.","correct":false},{"text":"Đặt ô nhập ra ngoài thẻ `form` thì nút gửi vẫn luôn gom được đầy đủ dữ liệu của ô đó.","correct":false}],"explain":"(1) Đúng — cách gắn nhãn với ô là cho `for` của nhãn trùng `id` của ô. (2) Đúng — khi đã khớp, bấm vào nhãn thì con trỏ tự nhảy vào ô, dùng rất tiện. (3) Sai — thiếu nhãn, phần mềm đọc màn hình chỉ báo 'ô trống' mà không rõ để điền gì, nên biểu mẫu kém thân thiện hơn hẳn với người khiếm thị. (4) Sai — ô nằm ngoài `form` không được gom khi bấm gửi, nên dữ liệu của ô đó có thể bị bỏ sót."},{"id":"UC-mc-701","type":"mc","topic":"E","grade":12,"level":"easy","question":"Rà soát tính 'nhất quán' của một trang web trước khi nộp chủ yếu là kiểm tra điều gì?","options":["Các trang con dùng chung phông chữ, màu sắc và khoảng cách hợp lí","Trang có nhiều màu sắc và phông chữ khác nhau càng tốt","Mỗi trang con nên tự chọn một kiểu riêng cho phong phú","Trang có càng nhiều hình ảnh động càng chuyên nghiệp"],"answer":0,"explain":"Nhất quán nghĩa là các trang con và các khu trong cùng dự án giống nhau về phông chữ, màu sắc, khoảng cách, tạo cảm giác liền mạch. Nhiều phông và màu khác nhau, hay mỗi trang một kiểu, lại khiến trang lộn xộn dù nội dung đủ. Số lượng hình ảnh động không quyết định tính nhất quán."},{"id":"UC-mc-702","type":"mc","topic":"E","grade":12,"level":"easy","question":"Huy bấm vào mục 'Sự kiện' trên thanh điều hướng thì trình duyệt báo không tìm thấy trang. Đây là lỗi gì?","options":["Ảnh không hiện","Phông chữ không nhất quán","Liên kết gãy","Trang không xem được trên điện thoại"],"answer":2,"explain":"Bấm liên kết mà trình duyệt báo không tìm thấy trang là dấu hiệu của liên kết gãy, thường do `href` trỏ sai tên tệp hoặc trang đích không tồn tại. Ảnh không hiện là ô ảnh vỡ chứ không phải báo không tìm thấy trang. Phông chữ không nhất quán và lỗi hiển thị trên điện thoại là vấn đề khác, không làm trình duyệt báo thiếu trang."},{"id":"UC-mc-703","type":"mc","topic":"E","grade":12,"level":"medium","question":"Một tấm ảnh trên trang hiện ra ô trống với dấu ảnh vỡ. Nguyên nhân nào sau đây phù hợp nhất và cần kiểm tra đầu tiên?","options":["Thuộc tính `href` của thanh điều hướng bị sai","Thuộc tính `src` trỏ sai đường dẫn hoặc quên chép ảnh vào thư mục dự án","Phông chữ của trang chưa được chọn","Chân trang chưa có dòng bản quyền"],"answer":1,"explain":"Ảnh vỡ thường do `src` trỏ sai đường dẫn, sai tên tệp hoặc quên chép ảnh vào thư mục dự án, nên đó là chỗ cần kiểm tra đầu tiên. `href` liên quan tới liên kết trang chứ không phải ảnh. Phông chữ và dòng bản quyền ở chân trang không liên quan gì tới việc một tấm ảnh có hiện được hay không."},{"id":"UC-mc-704","type":"mc","topic":"E","grade":12,"level":"medium","question":"Vì sao khi đóng gói dự án web, các liên kết và ảnh nên dùng đường dẫn tương đối trong thư mục dự án?","options":["Để trang tải nhanh hơn nhờ dùng ít mã hơn","Để trình duyệt tự đổi màu nền cho trang","Để trang tự động hiển thị đẹp trên điện thoại","Để chép cả thư mục sang máy khác hoặc tải lên mạng thì trang vẫn chạy đúng, không gãy liên kết hay vỡ ảnh"],"answer":3,"explain":"Đường dẫn tương đối trỏ theo vị trí bên trong thư mục dự án, nên khi chép cả thư mục sang máy khác hay tải lên dịch vụ lưu trữ, đường dẫn vẫn đúng và trang chạy y nguyên. Nó không nhằm tăng tốc độ tải, không đổi màu nền, cũng không tự làm trang hợp với điện thoại; việc hiển thị trên màn hình nhỏ là do cách chỉnh bố cục và CSS."},{"id":"UC-mc-705","type":"mc","topic":"E","grade":12,"level":"hard","question":"Trang của Lan mở trên máy tính ở nhà thì mọi liên kết đều tốt, nhưng sau khi đưa lên mạng, một số liên kết lại gãy. Nguyên nhân có khả năng nhất là gì?","options":["Dịch vụ lưu trữ web không hỗ trợ tệp `.html`","Tên tệp và tên trong `href` viết khác nhau về hoa thường, mà máy chủ trên mạng phân biệt hoa thường","Điện thoại không mở được trang web nói chung","Trang có quá nhiều hình ảnh nên máy chủ tự chặn liên kết"],"answer":1,"explain":"Máy ở nhà thường không phân biệt hoa thường nên `GioiThieu.html` và `gioithieu.html` vẫn mở được như nhau, nhưng nhiều máy chủ trên mạng lại phân biệt, nên chỉ cần gõ khác hoa thường là liên kết gãy. Dịch vụ lưu trữ web bình thường đều phục vụ tệp `.html`. Điện thoại vẫn mở được web, và số lượng ảnh không khiến máy chủ tự chặn liên kết."},{"id":"UC-tf-701","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Giữ nhất quán về phông chữ, màu sắc và khoảng cách giúp cả trang trông liền mạch, chuyên nghiệp hơn.","correct":true},{"text":"Viết các quy tắc CSS chung nhắm tới từng loại thẻ giúp đổi một chỗ là cả trang đổi theo.","correct":true},{"text":"Mỗi trang con nên chọn một phông chữ và bảng màu riêng để tạo cảm giác phong phú.","correct":false},{"text":"Nội dung đầy đủ thì tính nhất quán về hình thức không còn quan trọng nữa.","correct":false}],"explain":"(1) Đúng — nhất quán về phông, màu, khoảng cách làm trang liền mạch, chuyên nghiệp. (2) Đúng — dùng quy tắc CSS chung cho từng loại thẻ giúp đổi một chỗ là áp cho cả trang. (3) Sai — mỗi trang một kiểu khiến site lộn xộn như ba trang ghép lại, cần dùng chung một bộ quy ước. (4) Sai — dù nội dung đủ, hình thức lộn xộn vẫn làm người xem khó chịu, nên nhất quán vẫn quan trọng."},{"id":"UC-tf-702","type":"tf","topic":"E","grade":12,"level":"medium","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Kiểm thử trang web là tự đóng vai người xem, bấm thử từng liên kết và xem mọi ảnh có hiện đủ không.","correct":true},{"text":"Nên xem thử trang trên màn hình nhỏ như điện thoại vì nhiều người sẽ mở trang bằng điện thoại.","correct":true},{"text":"Chỉ cần trang chạy tốt trên máy tính là chắc chắn hiển thị tốt trên điện thoại.","correct":false},{"text":"Khi xem trên điện thoại, người dùng phải kéo ngang để đọc hết là dấu hiệu bố cục tốt.","correct":false}],"explain":"(1) Đúng — kiểm thử là thử lần lượt mọi liên kết và ảnh để phát hiện lỗi trước người khác. (2) Đúng — phần lớn người xem dùng điện thoại nên phải thử trên màn hình nhỏ. (3) Sai — trang đẹp trên máy tính vẫn có thể vỡ bố cục trên điện thoại vì màn hình hẹp hơn. (4) Sai — phải kéo ngang mới đọc hết là dấu hiệu bố cục chưa hợp; mục tiêu là chỉ cần cuộn dọc."},{"id":"UC-tf-703","type":"tf","topic":"E","grade":12,"level":"hard","question":"Cho biết mỗi phát biểu sau đúng hay sai:","statements":[{"text":"Đóng gói dự án là gom mọi tệp .html, tệp CSS và thư mục ảnh vào chung một thư mục.","correct":true},{"text":"Đưa trang lên một dịch vụ lưu trữ web sẽ cho một địa chỉ để ai cũng mở được qua Internet.","correct":true},{"text":"Chỉ cần gửi riêng một tệp .html cho bạn là bạn chắc chắn xem được trang đầy đủ cả ảnh.","correct":false},{"text":"Sau khi đưa lên mạng, trang luôn hiển thị đúng kể cả khi cấu trúc thư mục và đường dẫn thay đổi.","correct":false}],"explain":"(1) Đúng — đóng gói là gom toàn bộ tệp trang, CSS và thư mục ảnh vào chung một thư mục để chép hoặc nén gửi. (2) Đúng — dịch vụ lưu trữ web cấp một địa chỉ để bất kì ai gõ vào trình duyệt là mở được. (3) Sai — gửi mỗi tệp .html mà thiếu thư mục ảnh thì ảnh sẽ vỡ, phải gửi cả thư mục dự án. (4) Sai — trang chỉ hiển thị đúng khi giữ nguyên cấu trúc thư mục và đường dẫn như lúc kiểm thử."}]);
  LESSONS.push(
    {"id":"U12-01","stage":24,"order":1,"topic":"B","grade":12,"minutes":12,"title":"Thực hành kết nối và chia sẻ giữa các thiết bị số","intro":"Bạn đã học mạng máy tính hoạt động thế nào. Giờ chúng ta bắt tay làm thật: **nối** điện thoại, máy tính, máy in lại với nhau và **chia sẻ** tệp, màn hình, máy in giữa chúng một cách an toàn.","sections":[{"t":"story","text":"Nhóm bốn bạn lớp 12A2 ngồi ở nhà bạn Minh để hoàn thiện bài thuyết trình cuối kì. Ảnh chụp buổi khảo sát đang nằm trong điện thoại của Lan, phần chữ do Minh gõ trong máy tính, còn cả nhóm thì muốn in thử vài trang ra tờ giấy để soát lỗi. Rắc rối bắt đầu: làm sao đưa mấy chục tấm ảnh từ điện thoại Lan sang máy Minh mà không phải gửi từng cái qua tin nhắn?\n\nMinh thử cắm sợi cáp của điện thoại vào máy tính, một lúc sau máy hiện ra thư mục ảnh của Lan như một ổ đĩa. Nhưng bạn Huy ngồi máy khác lại không có cáp phù hợp, đành hỏi: \"Máy Minh với máy tớ cùng nối một cục phát Wi-Fi, vậy hai máy có thấy nhau không?\". Còn chiếc máy in duy nhất thì cắm vào máy của Minh, ba bạn kia loay hoay không biết in kiểu gì cho tiện.\n\nCả buổi loay hoay đó thật ra chỉ xoay quanh hai việc: **kết nối** các thiết bị lại, rồi **chia sẻ** thứ mình có cho nhau. Bài này sẽ hướng dẫn bạn làm gọn cả hai."},{"t":"h","text":"1) Ba cách kết nối thiết bị thường gặp"},{"t":"text","text":"Trước khi chia sẻ được bất cứ thứ gì, hai thiết bị phải \"nhìn thấy\" nhau qua một **đường truyền**. Trong thực tế bạn hay gặp ba cách: nối bằng **cáp**, nối qua **Wi-Fi** (cùng một mạng không dây), và nối qua **Bluetooth** (kết nối không dây tầm gần giữa hai thiết bị).\n\nMỗi cách hợp với một hoàn cảnh khác nhau. Cáp cho tốc độ ổn định và không cần cấu hình mạng, thích hợp khi chép khối lượng lớn như cả thư mục ảnh từ điện thoại sang máy tính. Wi-Fi giúp nhiều thiết bị trong cùng một phòng nối chung một cục phát rồi trao đổi mà không cần dây. Bluetooth tiện gửi vài tệp nhỏ hoặc nối tai nghe, chuột, loa ở khoảng cách gần vài mét."},{"t":"note","text":"Bẫy hay gặp với cáp điện thoại: cắm vào máy nhưng máy chỉ báo \"đang sạc\" mà không hiện thư mục ảnh. Nguyên nhân là điện thoại đang ở chế độ chỉ sạc; phải chọn lại thành **chế độ truyền tệp** trên màn hình điện thoại thì máy tính mới thấy dữ liệu."},{"t":"list","text":"Chọn cách kết nối theo tình huống:","items":["**Cáp**: chép nhiều dữ liệu, sạc kèm truyền, không phụ thuộc mạng; hạn chế là phải đúng loại đầu cắm.","**Wi-Fi**: nhiều thiết bị cùng mạng thấy nhau, phạm vi cả căn phòng; cần cùng một cục phát và cùng lớp mạng.","**Bluetooth**: gửi tệp nhỏ, nối thiết bị ngoại vi ở gần; chậm hơn và tầm ngắn, cần **ghép đôi** trước khi dùng.","**Điểm chung**: cả ba đều phải để thiết bị ở trạng thái cho phép kết nối, ví dụ bật Bluetooth hoặc bật chế độ truyền tệp khi cắm cáp."]},{"t":"h","text":"2) Chia sẻ tệp giữa các thiết bị trong cùng một mạng"},{"t":"text","text":"Khi hai máy tính cùng nối vào một mạng, ta có thể biến một thư mục trên máy này thành **thư mục dùng chung** để máy kia mở được qua mạng, thay vì phải chép ra USB. Người ta gọi thao tác đó là **chia sẻ thư mục**: bạn chọn thư mục, bật tính năng chia sẻ, và hệ điều hành sẽ cấp cho nó một đường dẫn mạng để máy khác truy cập.\n\nĐể máy bên kia tìm được, hai máy phải thuộc **cùng một mạng** và bật tính năng cho phép các máy thấy nhau. Khi đó, từ máy của Huy có thể mở phần mạng, thấy tên máy của Minh, bấm vào và duyệt đúng thư mục mà Minh đã chia sẻ. Với điện thoại, cách nhanh gọn hơn thường là gửi trực tiếp qua Bluetooth hoặc qua tính năng gửi tệp không dây tầm gần giữa hai máy."},{"t":"h","text":"3) Chia sẻ máy in và màn hình"},{"t":"text","text":"Máy in trong nhóm chỉ cắm vào một máy, nhưng cả nhóm vẫn in được nhờ **chia sẻ máy in**. Máy có gắn máy in bật chế độ chia sẻ; các máy khác trong cùng mạng thêm chiếc máy in đó vào danh sách của mình rồi in như in bằng máy in của chính nó. Lệnh in được gửi qua mạng tới máy chủ rồi mới ra giấy, nên máy chủ phải đang bật.\n\n**Chia sẻ màn hình** thì ngược lại về mục đích: không phải để in, mà để nhiều người cùng nhìn thấy những gì đang hiện trên một màn hình. Khi thuyết trình, Minh chiếu màn hình máy tính lên tivi hoặc máy chiếu trong phòng qua cáp hình hoặc qua kết nối không dây, để cả lớp cùng xem slide mà không phải chụm đầu vào một cái laptop."},{"t":"example","text":"Hình dung việc chia sẻ trong buổi làm bài của nhóm 12A2, nhìn từ máy của Minh:","code":"May cua Minh (may chu)\n  Thu muc chia se : Bai_Thuyet_Trinh  -> cho phep xem va sua\n  May in chia se  : May_in_phong_khach -> cho phep in\nMay cua Huy (cung mang Wi-Fi)\n  Mo phan mang -> thay \"May cua Minh\"\n  Vao thu muc Bai_Thuyet_Trinh, them anh cua Lan\n  Chon in -> May_in_phong_khach","output":"Huy mở được thư mục do Minh chia sẻ và bổ sung ảnh, đồng thời gửi lệnh in tới máy in cắm ở máy Minh. Cả hai việc đi qua mạng chung, không cần chép USB hay mang máy in sang."},{"t":"h","text":"4) Quyền truy cập và an toàn khi chia sẻ"},{"t":"text","text":"Chia sẻ tiện, nhưng mở một thư mục ra mạng nghĩa là người khác trong mạng có thể chạm vào dữ liệu của bạn. Vì thế khi bật chia sẻ, hệ điều hành luôn hỏi cấp **quyền truy cập** ở mức nào: chỉ cho **xem** (đọc) hay cho cả **sửa, xoá** (ghi). Với thư mục ảnh gốc quý giá, nên đặt quyền chỉ xem để không ai vô tình xoá; với thư mục nháp để cả nhóm cùng làm thì mới mở quyền sửa.\n\nMột nguyên tắc gọn để nhớ: **chỉ chia sẻ khi cần và tắt chia sẻ khi xong**. Đừng để một thư mục ở chế độ chia sẻ suốt ngày trên mạng công cộng như Wi-Fi quán cà phê hay thư viện, vì người lạ cùng mạng cũng có thể dò tới. Với Bluetooth cũng vậy: bước **ghép đôi** thường hiện một **mã** để hai bên xác nhận đúng thiết bị muốn nối, nên nếu tự dưng có yêu cầu ghép đôi lạ hiện lên mà bạn không chủ động thì hãy từ chối; tắt Bluetooth khi không dùng và chỉ nhận tệp từ thiết bị mình biết rõ."}],"keypoints":["Ba cách kết nối thường gặp: **cáp** (chép nhiều, ổn định), **Wi-Fi** (nhiều máy cùng mạng), **Bluetooth** (tệp nhỏ, tầm gần).","Muốn chia sẻ qua mạng, các thiết bị phải ở **cùng một mạng** và bật cho phép thấy nhau; **chia sẻ thư mục** giúp máy khác mở trực tiếp không cần USB.","**Chia sẻ máy in** để cả nhóm in qua một máy in chung; **chia sẻ màn hình** để nhiều người cùng xem một màn hình.","Khi chia sẻ phải đặt đúng **quyền truy cập** (chỉ xem hay cho sửa) và **chỉ chia sẻ khi cần, tắt khi xong** để giữ an toàn."],"quiz":["UC-mc-101","UC-mc-102","UC-mc-103","UC-mc-104","UC-mc-105","UC-tf-101","UC-tf-102","UC-tf-103","UD2-mc-061","UD2-mc-062","UD2-mc-063","UD2-mc-064","UD2-tf-031","UD2-tf-032"]},
    {"id":"U12-02","stage":24,"order":2,"topic":"E","grade":12,"minutes":12,"title":"Chuẩn bị dự án: lên ý tưởng và cấu trúc trang web","intro":"Trước khi gõ dòng lệnh đầu tiên, một trang web tốt bắt đầu từ **bản kế hoạch**: rõ mục đích, rõ người xem, rõ bố cục và cách các trang nối với nhau. Bài này dạy bước **chuẩn bị dự án** — nền móng cho cả chương làm web.","sections":[{"t":"story","text":"Lớp 12A được giao làm một trang web giới thiệu câu lạc bộ Guitar của trường để đăng lên cổng thông tin đoàn. Bạn Minh hào hứng mở máy, gõ ngay vài dòng, chèn đại mấy tấm ảnh chụp buổi tập, rồi thấy trang trông lộn xộn: chỗ thì chữ đè lên ảnh, chỗ thì trống huơ, người xem chẳng biết bấm vào đâu để xem lịch sinh hoạt.\n\nCô giáo xem qua liền hỏi: trang này làm cho ai xem, cần nói những gì, và sẽ có mấy trang? Minh ngớ người vì chưa nghĩ tới. Cả nhóm ngồi lại, lấy một tờ giấy A4 vẽ nháp khung màn hình và liệt kê nội dung. Chỉ sau mười lăm phút, mọi người đã hình dung được trang web sẽ ra sao — dù chưa viết thêm một dòng nào.\n\nCâu chuyện của Minh cho thấy một điều: phần khó nhất của làm web không nằm ở việc gõ mã, mà ở việc **nghĩ trước khi làm**. Đó chính là bước chuẩn bị dự án."},{"t":"h","text":"1) Xác định mục đích, người xem và nội dung"},{"t":"text","text":"Mọi dự án web đều phải trả lời được ba câu hỏi trước tiên. **Trang web này để làm gì?** (giới thiệu câu lạc bộ, bán đồ handmade, hay ghi lại nhật ký lớp). **Ai sẽ xem?** (thầy cô, bạn học, phụ huynh hay khách lạ trên mạng). **Cần truyền đạt những nội dung gì?** Trả lời rõ ba câu này giúp bạn không đi lạc và không thừa thiếu.\n\nTừ mục đích, ta lọc ra danh sách nội dung chính. Ví dụ trang câu lạc bộ Guitar cần: lời giới thiệu, lịch sinh hoạt, hình ảnh hoạt động, và cách liên hệ đăng ký. Những gì không phục vụ mục đích thì mạnh dạn bỏ, tránh làm trang rối và loãng thông tin. Việc hiểu **đối tượng người xem** cũng quyết định giọng văn, cỡ chữ và màu sắc: trang cho học sinh có thể trẻ trung, trang cho phụ huynh nên nghiêm túc, dễ đọc."},{"t":"h","text":"2) Phác thảo bố cục trang (wireframe)"},{"t":"text","text":"**Wireframe** là bản vẽ nháp khung của một trang, thường vẽ bằng bút chì trên giấy hoặc bằng công cụ vẽ đơn giản. Nó chỉ dùng các ô chữ nhật để đánh dấu chỗ đặt gì, chưa quan tâm màu mè hay ảnh thật. Nhờ vẽ nháp trước, cả nhóm thống nhất được vị trí mọi thứ mà không tốn công dựng đi dựng lại.\n\nMột trang web thông thường chia làm ba khu vực theo chiều dọc. **Đầu trang** (phần trên cùng) chứa tên hoặc logo và thanh điều hướng. **Thân trang** (phần giữa, lớn nhất) chứa nội dung chính. **Chân trang** (phần dưới cùng) chứa thông tin phụ như liên hệ, bản quyền. **Thanh điều hướng** là dãy các mục bấm được để nhảy sang trang khác, thường nằm ở đầu trang cho dễ thấy."},{"t":"list","text":"Khi vẽ wireframe, hãy đánh dấu rõ các khối sau:","items":["Đầu trang: chỗ đặt logo/tên và thanh điều hướng","Thân trang: các khối nội dung chính, sắp theo thứ tự ưu tiên đọc","Chân trang: liên hệ, thông tin nhóm, năm thực hiện","Ghi chú kích thước tương đối để biết khối nào to, khối nào nhỏ"]},{"t":"h","text":"3) Chuẩn bị tư liệu và tổ chức thư mục dự án"},{"t":"text","text":"Trang web sẽ dùng đến nhiều **tư liệu**: các đoạn văn bản, hình ảnh, đôi khi cả biểu tượng hay âm thanh. Nên gom và biên tập chúng trước: viết sẵn lời giới thiệu, chọn lọc ảnh đẹp và **đổi tên ảnh có nghĩa** (ví dụ `anh-buoi-tap.jpg` thay vì `IMG_2381.jpg`), nén ảnh cho nhẹ để trang tải nhanh.\n\nĐiều quan trọng của người làm web chuyên nghiệp là **tổ chức thư mục gọn gàng** ngay từ đầu. Thường có một thư mục gốc của dự án, bên trong tách riêng thư mục chứa ảnh và thư mục chứa các trang. Nhờ vậy khi trang cần gọi đến một tấm ảnh, đường dẫn luôn rõ ràng và không bị lạc tệp. Nếu vứt tất cả lẫn lộn một chỗ, chỉ cần vài chục tệp là bạn sẽ rối và dễ làm hỏng liên kết."},{"t":"example","text":"Một cách tổ chức thư mục dự án gọn gàng cho trang câu lạc bộ Guitar:","code":"du-an-guitar/\n├── index        (trang chủ)\n├── lich-sinh-hoat\n├── thu-vien-anh\n├── anh/\n│   ├── logo\n│   ├── anh-buoi-tap\n│   └── anh-bien-dien\n└── style       (định dạng chung)","output":"Thư mục gốc du-an-guitar chứa các trang ở ngoài, còn mọi hình ảnh nằm gọn trong thư mục con anh. Khi một trang cần hiện ảnh, chỉ việc trỏ vào thư mục anh nên đường dẫn ngắn và dễ quản lí."},{"t":"h","text":"4) Sơ đồ các trang và liên kết"},{"t":"text","text":"Một trang web hoàn chỉnh thường gồm nhiều trang. Để không bị rối, ta vẽ **sơ đồ trang** (sitemap): mỗi trang là một ô, mũi tên chỉ đường bấm từ trang này sang trang kia. Trang chủ thường đứng ở trung tâm, tỏa ra các trang con như lịch sinh hoạt, thư viện ảnh, liên hệ.\n\nSơ đồ này giúp bạn thấy trước **có bao nhiêu trang cần làm** và **trang nào nối với trang nào**. Nguyên tắc thân thiện là từ bất kì trang nào người xem cũng quay về được trang chủ, và không có trang nào bị 'lạc' — tức không có đường bấm nào dẫn tới. Có sơ đồ trong tay, khi bắt tay dựng thanh điều hướng ở bài sau, bạn chỉ việc chép lại đúng các đường liên kết đã vạch ra."},{"t":"note","text":"Bẫy thường gặp: bỏ qua bước lập kế hoạch mà lao vào làm ngay. Hậu quả là trang lộn xộn, phải sửa đi sửa lại, thư mục bừa bộn khiến ảnh không hiện. Mười lăm phút vẽ wireframe và sơ đồ trang trên giấy tiết kiệm cho bạn nhiều giờ chỉnh sửa về sau."}],"keypoints":["Bắt đầu bằng ba câu hỏi: trang **để làm gì**, **ai xem**, **nội dung chính** là gì","**Wireframe** là bản vẽ nháp khung trang: đầu trang, thân, chân trang và thanh điều hướng","Chuẩn bị tư liệu trước và **tổ chức thư mục gọn** (tách riêng thư mục ảnh) để không lạc tệp","Vẽ **sơ đồ trang** để thấy số trang và các liên kết trước khi dựng trang"],"quiz":["UC-mc-201","UC-mc-202","UC-mc-203","UC-mc-204","UC-mc-205","UC-tf-201","UC-tf-202","UC-tf-203","UD2-mc-065","UD2-mc-066","UD2-mc-067","UD2-mc-068","UD2-tf-033","UD2-tf-034"]},
    {"id":"U12-03","stage":24,"order":3,"topic":"E","grade":12,"minutes":12,"title":"Xây dựng phần đầu trang: header và logo","intro":"Sau khi đã phác thảo cấu trúc website ở bài trước, hôm nay em bắt tay dựng **phần đầu trang** (`header`) cho dự án: nơi đặt **logo** và **tiêu đề chính** để mọi người vừa mở trang đã nhận ra ngay đây là website của ai, về chủ đề gì.","sections":[{"t":"story","text":"Câu lạc bộ Sách của lớp 12A giao cho Lan làm một website nhỏ để giới thiệu hoạt động và danh sách sách hay. Lan đã có sẵn bản phác thảo trên giấy: trên cùng là một dải màu xanh chứa hình cuốn sách nhỏ bên trái và dòng chữ lớn 'Câu lạc bộ Sách 12A' ở giữa.\n\nLan mở tệp trang chủ ra và bắt đầu gõ nội dung, nhưng bạn phân vân: dòng tiêu đề với hình cuốn sách nên đặt ở đâu trong tệp cho gọn gàng? Nếu cứ để lẫn với phần giới thiệu ở giữa trang thì sau này sửa rất rối, mà mỗi trang lại làm một kiểu thì cả website trông chắp vá.\n\nBạn Khoa ngồi cạnh nhắc: 'Cái dải trên cùng đó gọi là phần đầu trang. Cậu gom nó vào một khu riêng, làm thật đẹp một lần, rồi trang nào cũng dùng y hệt thì website mới nhất quán.' Lan gật gù: hoá ra phần nhìn thì nhỏ nhưng lại là bộ mặt của cả trang."},{"t":"h","text":"1) Phần đầu trang là gì và gồm những gì"},{"t":"text","text":"**Phần đầu trang** là dải nội dung nằm trên cùng, xuất hiện đầu tiên khi người xem mở website. Nó đóng vai trò như tấm biển hiệu của một cửa hàng: chỉ liếc qua là biết đây là trang của tổ chức nào, về chủ đề gì. Trong dự án của em, phần đầu thường gồm hai thành phần chính là **logo** (hình đại diện nhỏ) và **tiêu đề chính** của website.\n\nĐể máy tính và người khác hiểu 'đây là khu vực đầu trang', ta gói cả cụm này vào thẻ `header`. Thẻ `header` không tự vẽ ra màu mè gì, nó chỉ đóng vai trò một chiếc hộp có ý nghĩa, gom logo và tiêu đề lại thành một khối riêng. Nhờ vậy khi cần trang trí hay di chuyển cả cụm đầu trang, em chỉ làm việc với một khối duy nhất thay vì từng mẩu rời rạc."},{"t":"text","text":"Em nên phân biệt **tiêu đề chính hiển thị trên trang** với dòng tiêu đề của cửa sổ trình duyệt. Tiêu đề chính nằm trong phần đầu trang, thường dùng thẻ tiêu đề cỡ lớn để người xem đọc thấy ngay giữa dải màu. Còn dòng chữ nhỏ trên tab trình duyệt là một nội dung khác, được khai báo ở phần đầu tệp và không nằm trong `header`.\n\nMột phần đầu trang tốt cần ngắn gọn: chỉ logo, tên website và có thể thêm một câu khẩu hiệu ngắn. Nhồi quá nhiều chữ hay ảnh vào đây sẽ làm người xem rối mắt và đẩy nội dung chính xuống quá thấp."},{"t":"h","text":"2) Chèn logo và chỉnh kích thước cho vừa"},{"t":"text","text":"Logo là một tấm ảnh, nên em chèn nó bằng thẻ ảnh và trỏ tới tệp hình đã chuẩn bị, ví dụ `logo.png` để trong thư mục dự án. Đừng quên ghi phần mô tả ảnh (thuộc tính `alt`) như 'Logo Câu lạc bộ Sách', vừa giúp người khiếm thị nghe được, vừa hiện ra khi ảnh lỡ không tải được.\n\nẢnh gốc thường rất to so với chỗ cần đặt, nên phải chỉnh kích thước cho vừa dải đầu trang. Cách gọn nhất là đặt chiều cao cố định bằng CSS, ví dụ cho ảnh logo cao `48px`, rồi để chiều rộng tự co theo cho ảnh không bị méo. Nếu ép cả chiều cao lẫn chiều rộng bằng những con số không cân xứng, hình sẽ bị kéo dẹt hoặc bè ra trông rất xấu."},{"t":"h","text":"3) Trang trí dải đầu trang bằng CSS"},{"t":"text","text":"Đến đây em dùng lại kiến thức CSS để biến khối `header` trơ trọi thành một dải đẹp mắt. Ba việc hay làm nhất là: tô **màu nền** cho cả dải để nó nổi bật khỏi phần thân, chọn **màu chữ** tương phản với nền để tiêu đề dễ đọc, và thêm một khoảng đệm bên trong để logo với chữ không dính sát mép.\n\nĐể logo và tiêu đề nằm cạnh nhau, canh giữa gọn gàng, cách hiện đại là cho `header` dùng bố cục linh hoạt rồi căn các phần tử theo trục. Khi đó em dễ dàng đặt logo bên trái, tiêu đề ở giữa, và mọi thứ tự canh đều theo chiều dọc. Chọn màu nền và màu chữ nên bám theo bảng màu chung của dự án đã thống nhất ở bài chuẩn bị, để phần đầu ăn nhập với toàn bộ website."},{"t":"example","text":"Đoạn mã dựng phần đầu trang cho website Câu lạc bộ Sách của Lan: một khối `header` chứa logo và tiêu đề, kèm vài dòng CSS để tô nền và canh giữa.","code":"<header class=\"dau-trang\">\n  <img src=\"logo.png\" alt=\"Logo Câu lạc bộ Sách\">\n  <h1>Câu lạc bộ Sách 12A</h1>\n</header>\n\n<style>\n.dau-trang {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 12px;\n  background: #1f6f54;\n  color: white;\n  padding: 16px;\n}\n.dau-trang img { height: 48px; }\n</style>","output":"Trên cùng trang hiện một dải màu xanh lá đậm. Ở giữa dải, hình logo nhỏ cao 48px nằm bên trái, ngay cạnh là dòng chữ trắng 'Câu lạc bộ Sách 12A' cỡ lớn. Logo và chữ được canh giữa theo cả chiều ngang lẫn chiều dọc, cách mép trên và mép dưới một khoảng đệm đều nhau."},{"t":"h","text":"4) Giữ phần đầu nhất quán trên mọi trang"},{"t":"list","text":"Website của em có nhiều trang (trang chủ, giới thiệu, danh sách sách...). Để phần đầu giống hệt nhau ở mọi trang, hãy nhớ:","items":["Dùng cùng một cấu trúc header: cùng logo, cùng tiêu đề, cùng thứ tự sắp xếp trên mọi trang","Gom các quy tắc trang trí vào một tệp CSS chung để mọi trang cùng lấy, sửa một chỗ là đổi cả website","Đặt tệp logo ở một vị trí cố định trong thư mục dự án để mọi trang trỏ tới đúng đường dẫn","Kiểm tra lần lượt từng trang xem dải đầu có lệch màu, lệch cỡ chữ hay sai logo không"]},{"t":"note","text":"Bẫy thường gặp: sao chép phần đầu sang trang mới rồi quên đổi đường dẫn logo nên ảnh không hiện, chỉ còn khung vỡ với dòng chữ mô tả. Một lỗi khác là mỗi trang tự sửa màu nền header một kiểu, khiến website trông chắp vá; hãy để mọi quy tắc màu và kích thước ở một tệp CSS chung thay vì gõ lại trên từng trang."}],"keypoints":["**Phần đầu trang** gói trong thẻ `header`, gồm **logo** và **tiêu đề chính**, là bộ mặt nhận diện của website","Logo là ảnh: chèn bằng thẻ ảnh có mô tả `alt`, chỉnh **kích thước** bằng cách cố định chiều cao để không méo","Dùng lại CSS để tô **màu nền**, chọn màu chữ tương phản và **canh giữa** logo với tiêu đề bằng bố cục linh hoạt","Giữ phần đầu **nhất quán** trên mọi trang: cùng cấu trúc, dùng chung một tệp CSS và đường dẫn logo cố định"],"quiz":["UC-mc-301","UC-mc-302","UC-mc-303","UC-mc-304","UC-mc-305","UC-tf-301","UC-tf-302","UC-tf-303","UD2-mc-069","UD2-mc-070","UD2-mc-071","UD2-mc-072","UD2-tf-035","UD2-tf-036"]},
    {"id":"U12-04","stage":24,"order":4,"topic":"E","grade":12,"minutes":12,"title":"Xây dựng phần thân và chân trang","intro":"Ở bài trước em đã dựng xong phần đầu trang với `logo` và tiêu đề. Bài này ta đổ **nội dung chính** vào phần thân (`main`) của dự án, chia thân trang thành các khu vực gọn gàng, rồi đóng trang bằng một **chân trang** (`footer`) đàng hoàng.","sections":[{"t":"story","text":"Nhóm của Lan đang làm trang web giới thiệu câu lạc bộ Sách của trường cho dự án cuối kì. Tuần trước cả nhóm đã dựng xong dải phía trên: có ảnh biểu tượng cuốn sách mở và dòng tên câu lạc bộ. Nhìn cũng ra dáng một trang web.\n\nNhưng khi Lan mở lại tệp để làm tiếp, bạn khựng lại. Dưới cái tên câu lạc bộ là một khoảng trắng mênh mông. Bao nhiêu thứ muốn đưa lên: đoạn giới thiệu câu lạc bộ, tấm ảnh buổi đọc sách cuối tuần, danh sách các hoạt động sắp tới, rồi cả số điện thoại liên hệ và dòng ghi tên nhóm làm trang. Lan gõ đại tất cả xuống, chữ với ảnh dồn thành một cục dính chặt, đọc rối cả mắt.\n\nBạn Huy trong nhóm góp ý: 'Hay mình chia trang ra từng khu như xếp đồ vào ngăn tủ ấy. Phần thân để mấy khối nội dung chính, mỗi khối một chuyện. Còn mấy dòng liên hệ với bản quyền thì gom hết xuống đáy trang cho gọn.' Ý tưởng chia khu và đóng đáy trang đó chính là việc ta làm hôm nay."},{"t":"h","text":"1) Phần thân trang chứa nội dung chính"},{"t":"text","text":"Một trang web thường có ba mảng lớn theo chiều dọc: **đầu trang** ở trên cùng, **thân trang** ở giữa và **chân trang** ở dưới cùng. Phần thân là nơi đặt **nội dung chính** mà người xem thật sự tìm đến: các đoạn văn giới thiệu, hình ảnh minh hoạ, danh sách hoạt động. Ta gói toàn bộ nội dung chính này trong thẻ `main`.\n\nBên trong `main`, các loại nội dung quen thuộc được đặt bằng những thẻ đã học ở bài trước: đoạn văn dùng `p`, hình ảnh dùng `img`, tiêu đề nhỏ dùng `h2` hay `h3`, danh sách gạch đầu dòng dùng `ul` và `li`. Điều mới ở bài này không phải là các thẻ đó, mà là cách **sắp xếp** chúng vào đúng chỗ trong dự án đang làm sao cho trang mạch lạc, dễ đọc."},{"t":"h","text":"2) Chia thân trang thành các khu vực"},{"t":"text","text":"Đổ hết mọi thứ thành một mạch dài như Lan làm lúc đầu sẽ khiến trang rối và khó chỉnh sửa. Cách gọn hơn là chia thân trang thành các **khu vực** (còn gọi là **khối**), mỗi khu lo một chủ đề. Câu lạc bộ Sách có thể chia thành: khu giới thiệu, khu ảnh hoạt động, khu danh sách sự kiện sắp tới.\n\nĐể nhóm nội dung thành một khu, ta bọc chúng trong thẻ `section` khi đó là một mục nội dung có chủ đề riêng, hoặc thẻ `div` khi chỉ cần một cái hộp để gom lại và tạo kiểu. Mỗi khu thường mở đầu bằng một tiêu đề `h2` để người đọc biết mình đang xem phần gì. Nhờ chia khu, sau này muốn sửa riêng khu ảnh mà không đụng khu giới thiệu, em chỉ việc tìm đúng `section` đó."},{"t":"example","text":"Cấu trúc phần thân trang của câu lạc bộ Sách sau khi chia thành ba khu:","code":"<main>\n  <section>\n    <h2>Về câu lạc bộ</h2>\n    <p>Câu lạc bộ Sách gặp nhau mỗi chiều thứ Bảy...</p>\n  </section>\n\n  <section>\n    <h2>Hình ảnh hoạt động</h2>\n    <img src=\"buoi-doc-sach.jpg\" alt=\"Buổi đọc sách cuối tuần\">\n  </section>\n\n  <section>\n    <h2>Sự kiện sắp tới</h2>\n    <ul>\n      <li>Giao lưu tác giả - 20/10</li>\n      <li>Đổi sách cũ - 05/11</li>\n    </ul>\n  </section>\n</main>","output":"Trang hiện ba khu xếp lần lượt từ trên xuống, mỗi khu có tiêu đề in đậm riêng: 'Về câu lạc bộ' với một đoạn giới thiệu, rồi 'Hình ảnh hoạt động' với tấm ảnh, cuối cùng 'Sự kiện sắp tới' với danh sách hai dòng gạch đầu dòng. Nội dung tách bạch, dễ đọc hơn hẳn một cục chữ liền."},{"t":"h","text":"3) Chân trang khép lại trang web"},{"t":"text","text":"**Chân trang** (`footer`) là dải nằm dưới cùng, đóng vai trò khép lại trang một cách gọn gàng và chuyên nghiệp. Đây không phải nơi đặt nội dung chính, mà để chứa những thông tin phụ nhưng cần có: cách **liên hệ** (email, số điện thoại, địa chỉ), dòng ghi **bản quyền**, tên nhóm hoặc người thực hiện, đôi khi thêm liên kết tới mạng xã hội.\n\nTa gói các thông tin này trong thẻ `footer`. Một mẹo quen thuộc cho dòng bản quyền là dùng kí hiệu `&copy;` để hiện ra dấu bản quyền, kèm năm và tên chủ nhân, ví dụ 'bản quyền thuộc câu lạc bộ Sách, 2026'. Nhờ đặt trong `footer`, phần này luôn được hiểu là chân trang dù nội dung thân trang dài hay ngắn."},{"t":"example","text":"Chân trang cho dự án của nhóm Lan:","code":"<footer>\n  <p>Liên hệ: clbsach@truong.edu.vn | 0987 654 321</p>\n  <p>&copy; 2026 Câu lạc bộ Sách - Nhóm 3 lớp 12A thực hiện</p>\n</footer>","output":"Dưới đáy trang hiện hai dòng nhỏ: một dòng cho thông tin liên hệ gồm email và số điện thoại, một dòng bản quyền có dấu © đứng trước năm và tên nhóm. Người xem cuộn xuống hết trang là gặp ngay khối này."},{"t":"h","text":"4) Áp CSS cho trang gọn gàng"},{"t":"list","text":"Chia khu xong nhưng chưa tạo kiểu thì các khu vẫn dính sát nhau. Vài thuộc tính CSS đơn giản dưới đây giúp trang thoáng và có trật tự:","items":["`padding`: tạo khoảng đệm bên trong một khu để chữ không dán sát mép","`margin`: tạo khoảng cách bên ngoài, giãn các khu ra xa nhau","`background-color`: đổi màu nền cho một khu hoặc riêng chân trang để phân biệt","`text-align`: canh lề nội dung, ví dụ canh giữa cho dòng bản quyền ở chân trang","`color`: đổi màu chữ cho hợp với màu nền đã chọn"]},{"t":"text","text":"Cách áp CSS gọn nhất là viết trong thẻ `style` ở phần đầu tệp, nhắm tới từng loại thẻ. Ví dụ đặt `section { margin: 16px; padding: 12px; }` để mọi khu đều có khoảng đệm và khoảng cách đều nhau, hay `footer { background-color: #222; color: white; text-align: center; }` để chân trang có nền tối, chữ trắng và canh giữa.\n\nMẹo làm việc là chỉnh từng chút một rồi lưu và mở lại trang trên trình duyệt để xem ngay kết quả. Đừng đặt quá nhiều màu sặc sỡ: một trang gọn gàng thường chỉ cần khoảng cách hợp lí và một hai màu nhấn là đã dễ nhìn. Bẫy thường gặp là gõ thẳng nội dung chính vào giữa `header` và `footer` mà quên bọc trong `main`, hoặc mở `<section>` mà thiếu `</section>`, khiến các khu lồng nhầm vào nhau và bố cục vỡ hết. Hãy mở đóng thẻ theo cặp và thụt lề cho dễ kiểm tra."}],"keypoints":["Nội dung chính của trang đặt trong **thân trang** (`main`): đoạn văn, hình ảnh, danh sách","Chia thân trang thành các **khu vực** bằng `section` hoặc `div`, mỗi khu một chủ đề, mở đầu bằng tiêu đề","**Chân trang** (`footer`) khép lại trang, chứa liên hệ và dòng **bản quyền** (`&copy;`), không phải nội dung chính","Dùng CSS như `padding`, `margin`, `background-color`, `text-align` để trang thoáng và gọn gàng"],"quiz":["UC-mc-401","UC-mc-402","UC-mc-403","UC-mc-404","UC-mc-405","UC-tf-401","UC-tf-402","UC-tf-403","UD2-mc-073","UD2-mc-074","UD2-mc-075","UD2-mc-076","UD2-tf-037","UD2-tf-038"]},
    {"id":"U12-05","stage":24,"order":5,"topic":"E","grade":12,"minutes":12,"title":"Liên kết trang và thanh điều hướng (menu)","intro":"Trang chủ đã đẹp, nhưng một website thật sự phải gồm **nhiều trang** nối với nhau. Bài này em học cách dùng thẻ `a` để đi từ trang này sang trang kia và dựng một **thanh điều hướng** (menu) để người xem chuyển trang chỉ bằng một cú nhấn.","sections":[{"t":"story","text":"Lớp em làm một trang web giới thiệu câu lạc bộ Guitar. Đến giờ dự án đã có bốn tệp riêng: trang chủ, trang giới thiệu thành viên, trang lịch sinh hoạt và trang liên hệ. Mỗi trang mở ra đều gọn gàng, đúng ý.\n\nNhưng khi bạn Minh thử xem, bạn kêu lên: mở trang chủ xong thì mắc kẹt, không có nút nào để sang trang thành viên, muốn xem trang khác phải nhờ em mở tệp giúp. Bốn trang đẹp mà rời rạc như bốn tờ giấy nằm riêng, người xem chẳng biết đường đi.\n\nĐiều còn thiếu là những **đường nối** giữa các trang, và một dải các nút đặt trên đầu mọi trang để bấm vào là nhảy sang trang tương ứng. Dải nút đó gọi là thanh điều hướng, còn đường nối chính là các liên kết. Bài này ta sẽ dựng chúng."},{"t":"h","text":"1) Thẻ liên kết a và thuộc tính href"},{"t":"text","text":"Trong HTML, muốn tạo một liên kết em dùng thẻ `a` (viết tắt của anchor, nghĩa là điểm neo). Phần chữ nằm giữa cặp thẻ `<a>` và `</a>` là chữ mà người xem nhìn thấy và bấm vào, còn địa chỉ trang cần tới được ghi trong thuộc tính `href`.\n\nVí dụ `<a href=\"lienhe.html\">Liên hệ</a>` sẽ hiện chữ **Liên hệ**; khi người xem nhấn vào, trình duyệt mở tệp `lienhe.html`. Chữ hiển thị và địa chỉ đích là hai thứ tách rời: em có thể cho hiện chữ tuỳ ý nhưng `href` phải trỏ đúng tên tệp, sai một chữ là trình duyệt báo không tìm thấy trang."},{"t":"h","text":"2) Liên kết tương đối giữa các tệp trong dự án"},{"t":"text","text":"Các trang trong cùng dự án thường nằm chung một thư mục, nên em không cần ghi cả địa chỉ dài. Chỉ cần ghi **tên tệp** đích là đủ; cách này gọi là **liên kết tương đối**, vì trình duyệt hiểu là tìm tệp ngay bên cạnh trang hiện tại.\n\nNhờ liên kết tương đối, khi em chép cả thư mục dự án sang máy khác hay tải lên mạng, các liên kết vẫn chạy đúng vì các tệp vẫn nằm cạnh nhau. Nếu em xếp trang vào thư mục con, đường dẫn phải phản ánh điều đó, ví dụ `anh/logo.png` nghĩa là tệp `logo.png` nằm trong thư mục con tên `anh`.\n\nMột bẫy hay gặp: tên tệp **phân biệt hoa thường** trên nhiều máy chủ, nên `TrangChu.html` và `trangchu.html` bị coi là hai tệp khác nhau và `href` phải gõ y hệt tên tệp thật. Ngoài ra nên tránh dấu cách và tiếng Việt có dấu trong tên tệp, hãy dùng chữ không dấu như `gioithieu.html` cho chắc."},{"t":"h","text":"3) Thanh điều hướng (menu) là gì"},{"t":"text","text":"**Thanh điều hướng** (menu) là một nhóm liên kết gom lại, thường đặt trên đầu mọi trang, trỏ tới các trang chính của website. Nhờ nó, dù đang ở trang nào người xem cũng thấy đủ các mục và bấm để nhảy tới bất kì trang nào chỉ trong một bước.\n\nVề bản chất, menu chỉ là **nhiều thẻ `a` xếp cạnh nhau**. Để trình duyệt và người khác hiểu đây là khu điều hướng, ta thường bọc chúng trong thẻ `nav`. Danh sách các mục hay được viết bằng thẻ danh sách `ul` và `li`, mỗi `li` chứa một liên kết, giúp cấu trúc rõ ràng và dễ căn chỉnh bằng CSS sau này."},{"t":"h","text":"4) Đặt menu giống nhau trên mọi trang"},{"t":"text","text":"Nguyên tắc quan trọng: menu phải **giống hệt nhau** và đặt ở cùng vị trí trên tất cả các trang. Người xem quen thấy các mục ở đúng chỗ, nên nếu trang này menu nằm trên, trang kia menu nằm dưới hoặc thiếu mục thì họ sẽ lạc.\n\nCách làm đơn giản khi mới học là chép nguyên đoạn menu vào phần đầu của từng tệp trang. Mỗi trang đều có đủ các liên kết tới những trang còn lại, kể cả liên kết trỏ về **chính trang chủ**. Nhờ vậy website tạo thành một mạng lưới khép kín: từ bất kì đâu cũng về được trang chủ và tới được mọi trang khác."},{"t":"h","text":"5) Đánh dấu mục đang mở"},{"t":"text","text":"Khi menu có nhiều mục, người xem dễ quên mình đang ở đâu. Vì thế ta thường **đánh dấu mục đang mở** cho nổi bật hơn các mục còn lại, chẳng hạn tô đậm, đổi màu chữ hoặc thêm một gạch dưới. Trên trang giới thiệu thì mục Giới thiệu được làm nổi, trên trang liên hệ thì mục Liên hệ được làm nổi.\n\nĐể làm được, ta gắn cho mục đang mở một dấu nhận biết, thường là một thuộc tính `class` riêng, rồi dùng CSS tô kiểu cho dấu đó. Mục đang mở cũng không nhất thiết phải là một liên kết bấm được, vì bấm vào chính trang đang xem thì chẳng đi đâu; nhiều trang để nó như một chữ tĩnh cho gọn."},{"t":"example","text":"Đoạn menu đặt ở đầu trang giới thiệu của câu lạc bộ Guitar. Mục Giới thiệu đang được đánh dấu bằng class `active`:","code":"<nav class=\"menu\">\n  <ul>\n    <li><a href=\"index.html\">Trang chu</a></li>\n    <li><a href=\"gioithieu.html\" class=\"active\">Gioi thieu</a></li>\n    <li><a href=\"lich.html\">Lich sinh hoat</a></li>\n    <li><a href=\"lienhe.html\">Lien he</a></li>\n  </ul>\n</nav>","output":"Trình duyệt hiện một dải bốn mục nằm ngang: Trang chu, Gioi thieu, Lich sinh hoat, Lien he. Nhấn vào mỗi mục sẽ mở tệp tương ứng trong cùng thư mục. Riêng mục Gioi thieu mang class active nên được CSS tô nổi bật, báo cho người xem biết họ đang ở trang này."}],"keypoints":["Thẻ `a` với thuộc tính `href` tạo liên kết: chữ giữa hai thẻ là phần bấm, `href` ghi tên tệp trang đích.","Trang trong cùng dự án dùng **liên kết tương đối** (chỉ ghi tên tệp), giúp website vẫn chạy khi chép hoặc tải lên mạng.","**Thanh điều hướng** (menu) là nhóm thẻ `a` bọc trong `nav`, phải **giống nhau và đặt cùng chỗ** trên mọi trang.","Nên **đánh dấu mục đang mở** (ví dụ bằng class riêng rồi tô CSS) để người xem biết mình đang ở trang nào."],"quiz":["UC-mc-501","UC-mc-502","UC-mc-503","UC-mc-504","UC-mc-505","UC-tf-501","UC-tf-502","UC-tf-503","UD2-mc-077","UD2-mc-078","UD2-mc-079","UD2-mc-080","UD2-tf-039","UD2-tf-040"]},
    {"id":"U12-06","stage":24,"order":6,"topic":"E","grade":12,"minutes":12,"title":"Thêm biểu mẫu vào trang web","intro":"Đến đây trang web của dự án đã có đầu trang, thân trang, chân trang và menu điều hướng đầy đủ. Nhưng trang mới chỉ **nói** với người xem, chưa **lắng nghe** họ. Bài này ta thêm một **biểu mẫu** (`form`) để người xem gửi lại thông tin: đăng ký, góp ý hay liên hệ với nhóm.","sections":[{"t":"story","text":"Trang web câu lạc bộ Sách của nhóm Lan giờ đã khá chỉn chu: có ảnh biểu tượng, các khu giới thiệu, danh sách sự kiện, thanh menu bấm sang từng trang mượt mà. Cả nhóm mang ra khoe với cô chủ nhiệm câu lạc bộ.\n\nCô xem xong gật gù khen đẹp, rồi hỏi một câu làm cả nhóm ngớ người: 'Thế bạn nào muốn xin vào câu lạc bộ thì làm sao hả các em? Trên trang có chỗ nào để bạn ấy điền tên, lớp, rồi bấm gửi cho nhóm mình không?' Lan nhìn lại trang: từ trên xuống dưới chỉ toàn chữ và ảnh để đọc, tuyệt nhiên không có một ô trống nào cho người xem gõ vào.\n\nHuy chợt nhớ hồi đăng ký thi học sinh giỏi trên mạng: có cái khung với mấy ô điền họ tên, lớp, email, chọn môn thi, cuối cùng bấm một nút là xong. 'Mình cần đúng cái khung đó,' Huy nói. Cái khung để người xem điền thông tin rồi gửi đi ấy chính là biểu mẫu, thứ ta đưa vào trang hôm nay."},{"t":"h","text":"1) Biểu mẫu giúp trang web lắng nghe người xem"},{"t":"text","text":"Từ đầu dự án đến giờ, trang web của em chỉ làm một việc: **đưa thông tin ra** cho người xem đọc và ngắm. Đó là luồng một chiều, từ trang tới người dùng. **Biểu mẫu** (`form`) mở thêm luồng ngược lại: người dùng **nhập thông tin vào** và gửi trở lại cho chủ trang. Nhờ vậy trang không chỉ nói mà còn biết lắng nghe.\n\nTrên các trang web em vẫn dùng hằng ngày, biểu mẫu có mặt khắp nơi: ô tìm kiếm, khung đăng nhập, phiếu đăng ký sự kiện, mục góp ý cuối trang. Với dự án câu lạc bộ Sách, một biểu mẫu **đăng ký thành viên** hoặc một khung **liên hệ** sẽ giúp trang trở nên hữu ích thật sự, chứ không chỉ để xem cho đẹp. Đây là điểm khác của bài này so với lúc học biểu mẫu ở dạng khái niệm: ta đưa hẳn một biểu mẫu vào đúng trang của dự án đang làm."},{"t":"h","text":"2) Khung biểu mẫu và nút gửi"},{"t":"text","text":"Toàn bộ một biểu mẫu được gói trong thẻ `form`. Cứ hình dung `form` như một cái phiếu giấy: mọi ô để điền và cái nút ở cuối đều nằm gọn trong tờ phiếu đó. Nhờ được gom chung, khi người dùng bấm gửi thì tất cả những gì họ đã điền trong phiếu mới đi cùng nhau một lượt.\n\nHai thành phần không thể thiếu của mọi biểu mẫu là **ô nhập** và **nút gửi**. Ô nhập cơ bản nhất tạo bằng thẻ `input`, cho một ô trống để người dùng gõ chữ vào, ví dụ ô điền họ tên. **Nút gửi** thường là một nút loại `submit`: khi bấm vào, trình duyệt gom hết dữ liệu trong `form` và gửi đi. Thiếu nút gửi thì người dùng có điền xong cũng chẳng có cách nào chuyển thông tin đến cho nhóm."},{"t":"example","text":"Một khung liên hệ tối giản cho trang câu lạc bộ Sách, mới chỉ có một ô nhập và một nút gửi:","code":"<form>\n  <input type=\"text\" placeholder=\"Họ và tên của bạn\">\n  <button type=\"submit\">Gửi</button>\n</form>","output":"Trên trang hiện một ô trống dài với dòng chữ mờ 'Họ và tên của bạn' gợi ý bên trong, ngay cạnh là một nút bấm ghi chữ 'Gửi'. Người xem gõ tên vào ô rồi bấm nút để gửi thông tin đi."},{"t":"h","text":"3) Các loại trường nhập thông tin"},{"t":"list","text":"Một phiếu đăng ký thật cần nhiều kiểu ô khác nhau chứ không chỉ ô gõ chữ. Tuỳ thông tin muốn thu, ta chọn loại **trường nhập** cho phù hợp:","items":["Ô văn bản (`input` loại `text`): điền chuỗi ngắn một dòng như họ tên, lớp","Ô email (`input` loại `email`): điền địa chỉ email, trình duyệt tự nhắc nếu sai dạng","Ô chọn một trong nhiều (`radio`): chỉ được chọn đúng một, ví dụ chọn khối lớp","Ô đánh dấu (`checkbox`): được chọn nhiều mục cùng lúc, ví dụ chọn các nhóm muốn tham gia","Danh sách xổ xuống (`select`): bấm ra một danh sách để chọn một mục, tiết kiệm chỗ","Vùng văn bản (`textarea`): ô rộng nhiều dòng cho đoạn dài như lời nhắn, góp ý"]},{"t":"h","text":"4) Nhãn gắn với ô nhập giúp dễ dùng"},{"t":"text","text":"Một ô trống trơ trọi thì người dùng biết gõ gì vào? Vì thế mỗi ô nhập cần một **nhãn** (`label`) đứng kèm, ghi rõ ô đó để điền thông tin gì, chẳng hạn 'Họ và tên', 'Email', 'Lời nhắn'. Nhãn không chỉ là dòng chữ trang trí, mà được **gắn** thật sự với ô nhập: ta cho thuộc tính `for` của nhãn trùng với `id` của ô. Khi đã gắn đúng, người dùng bấm vào chữ nhãn là con trỏ tự nhảy vào đúng ô, dùng rất tiện.\n\nGắn nhãn còn quan trọng cho **trợ năng**, tức khả năng dùng được cho mọi người. Người khiếm thị thường lướt web bằng phần mềm đọc màn hình đọc to nội dung lên. Khi con trỏ tới một ô có nhãn gắn đúng, phần mềm đọc luôn nhãn đó, người dùng biết ngay ô này cần điền gì. Nếu ô không có nhãn, họ chỉ nghe thấy 'một ô trống' mà không rõ để làm gì. Một biểu mẫu có nhãn đầy đủ là biểu mẫu thân thiện với tất cả người xem."},{"t":"example","text":"Biểu mẫu đăng ký thành viên câu lạc bộ Sách với nhãn gắn cho từng ô:","code":"<form>\n  <label for=\"ten\">Họ và tên:</label>\n  <input type=\"text\" id=\"ten\">\n\n  <label for=\"mail\">Email:</label>\n  <input type=\"email\" id=\"mail\">\n\n  <label for=\"nhan\">Lời nhắn:</label>\n  <textarea id=\"nhan\"></textarea>\n\n  <button type=\"submit\">Đăng ký</button>\n</form>","output":"Trang hiện một phiếu đăng ký: dòng 'Họ và tên:' kèm ô gõ chữ, dòng 'Email:' kèm ô email, dòng 'Lời nhắn:' kèm một khung rộng nhiều dòng, cuối cùng là nút 'Đăng ký'. Bấm vào chữ 'Email:' thì con trỏ nhảy ngay vào ô email nhờ `for` khớp với `id`."},{"t":"note","text":"Bẫy thường gặp: quên đặt nút gửi, khiến người dùng điền xong không có cách nào gửi đi; hoặc đặt các ô nhập ra ngoài thẻ `form`, làm chúng không được gom cùng khi bấm gửi. Một lỗi hay gặp nữa là viết nhãn nhưng để `for` của nhãn không khớp với `id` của ô, khi đó nhãn chỉ còn là chữ suông, bấm vào không nhảy vào ô và phần mềm đọc màn hình cũng không đọc kèm được. Hãy kiểm tra từng cặp `for` và `id` cho trùng nhau."}],"keypoints":["**Biểu mẫu** (`form`) mở luồng ngược để người xem **nhập và gửi** thông tin về cho chủ trang, thay vì chỉ đọc","Mọi biểu mẫu cần **ô nhập** (`input`, `textarea`...) và **nút gửi** (`submit`) gói chung trong thẻ `form`","Chọn đúng loại trường: `text`, `email`, `radio` (chọn một), `checkbox` (chọn nhiều), `select`, `textarea` (đoạn dài)","**Nhãn** (`label`) gắn với ô nhập qua `for` khớp `id` giúp dễ dùng và thân thiện với **trợ năng**"],"quiz":["UC-mc-601","UC-mc-602","UC-mc-603","UC-mc-604","UC-mc-605","UC-tf-601","UC-tf-602","UC-tf-603","UD2-mc-081","UD2-mc-082","UD2-mc-083","UD2-mc-084","UD2-tf-041","UD2-tf-042"]},
    {"id":"U12-07","stage":24,"order":7,"topic":"E","grade":12,"minutes":12,"title":"Hoàn thiện và kiểm thử trang web","intro":"Sáu bài vừa qua nhóm em đã dựng đủ **đầu trang**, **thân trang**, **chân trang**, **thanh điều hướng** và cả **biểu mẫu**. Bài cuối này ta lùi lại một bước, rà soát cho cả trang **nhất quán**, **kiểm thử** từng liên kết và hình ảnh, xem thử trên **điện thoại**, rồi **đóng gói** và đưa trang lên mạng.","sections":[{"t":"story","text":"Đến hạn nộp dự án, nhóm của Lan mở lại trang web câu lạc bộ Sách để xem lần cuối trước khi gửi cô. Ai cũng nghĩ xong rồi, chỉ việc nộp thôi. Nhưng vừa cuộn từ trên xuống, cả nhóm bắt đầu thấy sờ sợ.\n\nTrang chủ dùng phông chữ tròn trịa dễ thương, sang trang Giới thiệu tự nhiên chữ lại vuông cứng như đổi người viết. Nút bấm ở đầu trang màu xanh, xuống cuối lại có nút màu cam chẳng ăn nhập gì. Huy bấm thử vào mục 'Sự kiện' trên thanh điều hướng thì trình duyệt báo không tìm thấy trang. Một tấm ảnh buổi đọc sách thì hiện ra ô trống với dấu ảnh vỡ. Lan lấy điện thoại mở trang lên xem thì chữ nhỏ li ti, mấy khối nội dung tràn ra ngoài mép màn hình phải kéo ngang mới đọc hết.\n\n'Nội dung mình làm đủ cả rồi, nhưng nhìn như ba trang của ba người ghép lại,' Lan thở dài. Cô giáo đi ngang góp ý: 'Phần khó không phải là viết thêm, mà là ngồi soát lại cho cả trang thành một khối gọn gàng, rồi thử đủ mọi đường xem có chỗ nào gãy không. Xong hết mới tính chuyện đưa lên mạng.' Đó chính là công việc của bài hôm nay."},{"t":"h","text":"1) Rà soát tính nhất quán trên toàn trang"},{"t":"text","text":"Một trang web trông chuyên nghiệp hay không phần lớn nằm ở sự **nhất quán**: các trang con và các khu trong cùng dự án phải giống nhau về **phông chữ**, **màu sắc** và **khoảng cách**. Khi mỗi trang một kiểu như dự án của Lan, người xem có cảm giác lộn xộn dù nội dung vẫn đủ. Vì thế trước khi nộp, ta rà lại toàn bộ để mọi thứ ăn khớp.\n\nMẹo giữ nhất quán là chọn sẵn một bộ quy ước rồi áp cho cả trang: một hoặc hai phông chữ, một bảng màu nhỏ gồm một màu nền, một màu chữ và một hai màu nhấn, cùng một mức khoảng cách chung giữa các khu. Thay vì mỗi khu đặt kiểu riêng, ta viết các quy tắc `CSS` chung nhắm tới từng loại thẻ như `body`, `h2`, `footer`, để đổi một chỗ là cả trang đổi theo. Càng ít ngoại lệ, trang càng liền mạch."},{"t":"list","text":"Bảng kiểm nhất quán nên rà trước khi nộp:","items":["Phông chữ: mọi trang con dùng chung một bộ, không chỗ tròn chỗ vuông","Màu sắc: nút, tiêu đề, liên kết theo đúng bảng màu đã chọn","Khoảng cách: các khu cách nhau đều, chữ không dán sát mép","Kích thước chữ: tiêu đề, đoạn văn, chú thích có cỡ thống nhất giữa các trang","Cách xưng hô và chính tả: giọng văn và cách viết đồng nhất toàn site"]},{"t":"h","text":"2) Kiểm thử liên kết và hình ảnh"},{"t":"text","text":"**Kiểm thử** là bước tự mình đóng vai người xem, lần lượt thử mọi thao tác để phát hiện chỗ hỏng trước khi người khác gặp phải. Hai lỗi hay gặp nhất ở dự án web học sinh là **liên kết gãy** và **ảnh không hiện**.\n\nLiên kết gãy xảy ra khi thuộc tính `href` trỏ tới một trang không tồn tại hoặc gõ sai tên tệp, bấm vào thì trình duyệt báo không tìm thấy. Ảnh không hiện thường do `src` trỏ sai đường dẫn, sai tên tệp hoặc quên chép ảnh vào thư mục dự án, kết quả là ô ảnh vỡ. Cách kiểm là bấm thử **lần lượt từng liên kết** trên thanh điều hướng và trong nội dung, xem có mở đúng trang không; đồng thời cuộn hết trang xem **mọi ảnh** có hiện đủ không. Ghi lại chỗ nào lỗi rồi sửa `href` hoặc `src` cho đúng, kiểm lại tới khi sạch lỗi."},{"t":"note","text":"Bẫy thường gặp: gõ tên tệp sai hoa thường, ví dụ liên kết trỏ tới `GioiThieu.html` nhưng tệp thật lại tên `gioithieu.html`. Trên máy của em ở nhà có thể vẫn mở được, nhưng khi đưa lên mạng nhiều máy chủ phân biệt hoa thường nên liên kết sẽ gãy. Hãy đặt tên tệp thống nhất, nên viết thường không dấu không khoảng trắng, và gõ đúng y hệt trong `href` và `src`."},{"t":"h","text":"3) Xem trên màn hình nhỏ"},{"t":"text","text":"Phần lớn bạn bè sẽ mở trang bằng **điện thoại** chứ không phải máy tính, mà màn hình điện thoại hẹp hơn nhiều. Một trang đẹp trên máy tính vẫn có thể vỡ bố cục trên điện thoại: chữ quá nhỏ, các khối tràn ra ngoài mép phải kéo ngang mới đọc hết như trang của Lan. Vì vậy phải **xem thử trên màn hình nhỏ** rồi chỉnh cho hợp lí.\n\nCách thử nhanh là thu hẹp cửa sổ trình duyệt lại thật gọn, hoặc dùng chế độ xem điện thoại có sẵn trong công cụ của trình duyệt, để mô phỏng màn hình hẹp. Vài cách chỉnh phổ thông giúp trang dễ đọc trên điện thoại: đặt ảnh co giãn theo bề ngang khung chứa thay vì cố định một cỡ lớn, để các khu tự xuống hàng khi hết chỗ thay vì nằm ngang cứng nhắc, và tránh đặt bảng hay khối quá rộng. Mục tiêu là người xem không phải kéo ngang, chỉ cần cuộn dọc là đọc trọn trang."},{"t":"h","text":"4) Đóng gói và đưa trang lên mạng"},{"t":"text","text":"Khi trang đã nhất quán, hết lỗi và xem tốt trên điện thoại, ta **đóng gói** để nộp hoặc chia sẻ. Đóng gói nghĩa là gom **toàn bộ tệp của dự án** vào chung một thư mục: các tệp `.html`, tệp `.css` nếu tách riêng, và **thư mục ảnh**. Đường dẫn trong `href` và `src` phải là **đường dẫn tương đối** trỏ đúng trong thư mục này, nhờ vậy chép cả thư mục sang máy khác trang vẫn chạy y nguyên. Nén cả thư mục thành một tệp `.zip` là cách gửi gọn gàng.\n\nMuốn ai cũng xem được qua Internet chứ không chỉ mở tệp trên máy mình, ta cần **đưa trang lên mạng**, còn gọi là **xuất bản** hoặc **triển khai**. Ở mức phổ thông, cách làm là tải toàn bộ thư mục dự án lên một **dịch vụ lưu trữ web** miễn phí; dịch vụ sẽ cấp một **địa chỉ** (đường dẫn) để bất kì ai gõ vào trình duyệt là mở được trang. Điểm cần nhớ: trang trên mạng chỉ hiển thị đúng nếu cấu trúc thư mục và đường dẫn giữ nguyên như lúc kiểm thử ở máy."},{"t":"example","text":"Cấu trúc thư mục dự án của nhóm Lan sau khi đóng gói gọn gàng, sẵn sàng nén hoặc tải lên:","code":"clb-sach/\n  index.html        (trang chu)\n  gioithieu.html    (trang gioi thieu)\n  sukien.html       (trang su kien)\n  style.css         (kieu chung cho ca site)\n  anh/\n    logo.png\n    buoi-doc-sach.jpg","output":"Toàn bộ dự án nằm gọn trong một thư mục `clb-sach`. Các tệp trang đặt chung một chỗ, ảnh gom vào thư mục con `anh`. Vì mọi liên kết và ảnh đều trỏ theo đường dẫn tương đối trong thư mục này nên chép sang máy khác hoặc tải lên dịch vụ lưu trữ, trang vẫn chạy đúng, không gãy liên kết cũng không vỡ ảnh. Mẹo cuối trước khi nộp: đừng thử một lần rồi gửi luôn, hãy rà nhiều vòng và nhờ một bạn ngoài nhóm mở thử bằng máy lẫn điện thoại của bạn ấy, vì người mới thường thấy lỗi mà nhóm làm quen tay đã bỏ sót."}],"keypoints":["Rà soát **nhất quán** cả site: chung **phông chữ**, **bảng màu** và **khoảng cách**, dùng quy tắc CSS chung để đổi một chỗ là cả trang đổi theo","**Kiểm thử** bằng cách bấm thử từng liên kết và cuộn xem mọi ảnh, sửa `href` hoặc `src` sai cho hết **liên kết gãy** và **ảnh không hiện**","**Xem trên màn hình nhỏ** (điện thoại): để ảnh co giãn, khối tự xuống hàng, người xem chỉ cần cuộn dọc chứ không phải kéo ngang","**Đóng gói** gom mọi tệp và thư mục ảnh dùng **đường dẫn tương đối**, rồi **đưa lên dịch vụ lưu trữ web** để có địa chỉ ai cũng xem được"],"quiz":["UC-mc-701","UC-mc-702","UC-mc-703","UC-mc-704","UC-mc-705","UC-tf-701","UC-tf-702","UC-tf-703","UD2-mc-085","UD2-mc-086","UD2-mc-087","UD2-mc-088","UD2-tf-043","UD2-tf-044"]}
  );
})();
